#[derive(Clone, Debug)]
struct PlatformCount {
    name: String,
    count: usize,
}

#[derive(Clone, Debug, Default)]
struct NavigationCatalog {
    platforms: Vec<PlatformDefinition>,
    categories: Vec<PlatformCategory>,
    parents: Vec<ParentRelationship>,
    playlists: Vec<PlaylistDocument>,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
enum NavigationNodeKey {
    Category(String),
    Platform(String),
    Playlist(String),
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct NavigationEntry {
    kind: &'static str,
    key: String,
    name: String,
    depth: usize,
    game_count: usize,
    visible_in_big_box: bool,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct RelatedGamesSectionPayload {
    key: &'static str,
    label: &'static str,
    profile_source: RelatedProfileSource,
    items: Vec<RelatedGameSuggestion>,
}

#[derive(Clone, Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct RelatedGamesPayload {
    version: u32,
    game_id: String,
    metadata_database_loaded: bool,
    candidate_count: usize,
    sections: Vec<RelatedGamesSectionPayload>,
}

const MAX_DESKTOP_NOTIFICATIONS: usize = 128;
const MAX_DESKTOP_NOTIFICATION_MESSAGE_BYTES: usize = 4096;

#[derive(Clone, Debug, Eq, PartialEq)]
struct DesktopNotification {
    message: String,
    raised_at: String,
    is_error: bool,
    is_read: bool,
}

