    pub fn poll_big_box_gamepad_action(mut self: Pin<&mut Self>) -> QString {
        let (action, status, connected_count) = {
            let engine = &mut self.as_mut().rust_mut().big_box_input_engine;
            let action = engine.poll_action();
            (
                action,
                engine.backend_status().label(),
                engine.connected_gamepad_count(),
            )
        };
        let connected_count = saturating_i32(connected_count);
        if *self.as_ref().big_box_gamepad_connected_count() != connected_count {
            self.as_mut()
                .set_big_box_gamepad_connected_count(connected_count);
        }
        if self.as_ref().big_box_gamepad_status().to_string() != status {
            self.as_mut().set_big_box_gamepad_status(qstring(status));
        }
        action
            .map(BigBoxInputAction::key)
            .map(qstring)
            .unwrap_or_default()
    }

    pub fn submit_big_box_controller_event(
        mut self: Pin<&mut Self>,
        device_id: i32,
        binding: QString,
        pressed: bool,
    ) -> bool {
        let Ok(device_id) = u64::try_from(device_id) else {
            return false;
        };
        let Some(binding) = ControllerBinding::parse(binding.to_string().trim()) else {
            return false;
        };
        let event = if pressed {
            GamepadInputEvent::Pressed { device_id, binding }
        } else {
            GamepadInputEvent::Released { device_id, binding }
        };
        self.as_mut()
            .rust_mut()
            .big_box_input_engine
            .submit_semantic_event(event);
        true
    }

    pub fn select_big_box_screensaver_candidate(
        mut self: Pin<&mut Self>,
        avoid_game_id: QString,
    ) -> i32 {
        let avoid_game_id = avoid_game_id.to_string();
        let counter = self
            .as_ref()
            .rust()
            .random_selection_counter
            .wrapping_add(1);
        self.as_mut().rust_mut().random_selection_counter = counter;
        let clock_entropy = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs().rotate_left(17) ^ u64::from(duration.subsec_nanos()))
            .unwrap_or_default();
        let selected = {
            let this = self.as_ref();
            let candidates = &this.rust().big_box_screensaver_candidates;
            select_screensaver_candidate_index(
                candidates,
                (!avoid_game_id.is_empty()).then_some(avoid_game_id.as_str()),
                clock_entropy ^ counter.wrapping_mul(0x9e37_79b9_7f4a_7c15),
            )
        };
        selected.map(saturating_i32).unwrap_or(-1)
    }

    pub fn big_box_screensaver_swap_time_ms(&self, entropy: i32) -> i32 {
        let entropy = u32::try_from(entropy).map(u64::from).unwrap_or_default();
        saturating_i32(self.rust().big_box_screensaver_policy.swap_time_ms(entropy) as usize)
    }

