    pub fn apply_game_attribute_filters(
        mut self: Pin<&mut Self>,
        state_filter: QString,
        missing_media_filter: QString,
        include_hidden: bool,
        include_broken: bool,
    ) -> bool {
        let state_filter = state_filter.to_string();
        let Some(state_filter) = GameStateFilter::from_key(&state_filter) else {
            self.as_mut().set_status_message(qstring(format!(
                "Unknown game-state filter: {state_filter}"
            )));
            return false;
        };
        let missing_media_filter = missing_media_filter.to_string();
        let Some(missing_media_filter) = MissingMediaFilter::from_key(&missing_media_filter) else {
            self.as_mut().set_status_message(qstring(format!(
                "Unknown missing-media filter: {missing_media_filter}"
            )));
            return false;
        };

        self.as_mut()
            .set_game_state_filter(qstring(state_filter.key()));
        self.as_mut()
            .set_missing_media_filter(qstring(missing_media_filter.key()));
        self.as_mut().set_include_hidden_games(include_hidden);
        self.as_mut().set_include_broken_games(include_broken);
        self.as_mut().refresh_filtered_games();
        true
    }

    pub fn apply_game_sort(mut self: Pin<&mut Self>, sort: QString, descending: bool) -> bool {
        let requested = sort.to_string();
        let Some(sort) = GameSort::from_key(&requested) else {
            self.as_mut()
                .set_status_message(qstring(format!("Unknown game sort: {requested}")));
            return false;
        };
        let launchbox_root = self.as_ref().rust().launchbox_root.clone();
        if launchbox_root.is_some() && self.as_ref().library_operation_active() {
            self.as_mut()
                .set_status_message(qstring("Wait for the current library operation to finish."));
            return false;
        }

        self.as_mut().set_game_sort(qstring(sort.key()));
        self.as_mut().set_game_sort_descending(descending);
        self.as_mut().refresh_filtered_games();
        if let Some(root) = launchbox_root {
            let generation = self.as_ref().rust().request_generation;
            self.as_mut().set_writing(true);
            self.as_mut()
                .set_status_message(qstring("Saving Arrange By settings in the background..."));
            let qt_thread = self.as_ref().qt_thread();
            let spawn_result = std::thread::Builder::new()
                .name("launchbox-sort-settings-write".to_string())
                .spawn(move || {
                    let result = write_game_sort_settings(root, sort, descending);
                    qt_thread
                        .queue(move |mut controller| {
                            controller
                                .as_mut()
                                .finish_game_sort_write(generation, result);
                        })
                        .ok();
                });
            if let Err(error) = spawn_result {
                self.as_mut().set_writing(false);
                self.as_mut().set_status_message(qstring(format!(
                    "Could not start Arrange By settings writer: {error}"
                )));
            }
        }
        true
    }

    pub fn apply_list_view(mut self: Pin<&mut Self>, list_view: bool) -> bool {
        let previous = *self.as_ref().list_view();
        if previous == list_view {
            return true;
        }
        let launchbox_root = self.as_ref().rust().launchbox_root.clone();
        if launchbox_root.is_some() && !self.as_mut().begin_library_mutation() {
            return false;
        }

        self.as_mut().set_list_view(list_view);
        if let Some(root) = launchbox_root {
            let generation = self.as_ref().rust().request_generation;
            self.as_mut().set_writing(true);
            self.as_mut()
                .set_status_message(qstring("Saving library view mode in the background..."));
            let qt_thread = self.as_ref().qt_thread();
            let spawn_result = std::thread::Builder::new()
                .name("launchbox-view-mode-settings-write".to_string())
                .spawn(move || {
                    let result = write_list_view_setting(root, list_view);
                    qt_thread
                        .queue(move |mut controller| {
                            controller
                                .as_mut()
                                .finish_list_view_write(generation, previous, result);
                        })
                        .ok();
                });
            if let Err(error) = spawn_result {
                self.as_mut().set_writing(false);
                self.as_mut().set_list_view(previous);
                self.as_mut().set_status_message(qstring(format!(
                    "Could not start library view-mode settings writer: {error}"
                )));
                return false;
            }
        }
        true
    }

    pub fn apply_list_view_columns(mut self: Pin<&mut Self>, request_payload: QString) -> bool {
        if !self.as_mut().initialize_launchbox_ui_state() {
            return false;
        }
        let payload =
            match serde_json::from_str::<ListViewLayoutPayload>(&request_payload.to_string()) {
                Ok(payload) => payload,
                Err(error) => {
                    self.as_mut().set_status_message(qstring(format!(
                        "Could not decode LaunchBox list layout: {error}"
                    )));
                    return false;
                }
            };
        let (layout, next_state) = match payload.validate(&self.as_ref().rust().ui_state) {
            Ok(layout) => layout,
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not apply LaunchBox list layout: {error}"
                )));
                return false;
            }
        };
        let launchbox_root = self.as_ref().rust().launchbox_root.clone();
        if launchbox_root.is_some() && !self.as_mut().begin_library_mutation() {
            return false;
        }
        let Some(ui_state_path) = self.as_ref().rust().ui_state_file.clone() else {
            self.as_mut()
                .set_status_message(qstring("The LaunchBox desktop layout path is unavailable."));
            return false;
        };
        let previous_layout = self.as_ref().rust().list_view_column_layout.clone();
        let previous_state = self.as_ref().rust().ui_state.clone();
        if let Err(error) = next_state.save_atomic(&ui_state_path) {
            self.as_mut().set_status_message(qstring(format!(
                "Could not save LaunchBox list column widths: {error}"
            )));
            return false;
        }

        self.as_mut().rust_mut().list_view_column_layout = layout.clone();
        self.as_mut().apply_launchbox_ui_state(next_state);
        let Some(root) = launchbox_root else {
            self.as_mut()
                .set_status_message(qstring("Saved host-specific list column widths."));
            return true;
        };

        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut().set_status_message(qstring(
            "Saving LaunchBox list columns in the background...",
        ));
        let qt_thread = self.as_ref().qt_thread();
        let queued_previous_layout = previous_layout.clone();
        let queued_previous_state = previous_state.clone();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-list-column-settings-write".to_string())
            .spawn(move || {
                let result = write_list_view_column_settings(root, layout);
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_list_view_columns_write(
                            generation,
                            queued_previous_layout,
                            queued_previous_state,
                            result,
                        );
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            let rollback_error = self
                .as_mut()
                .restore_list_view_layout(previous_layout, previous_state);
            let rollback = rollback_error
                .map(|rollback| format!(" Host-state rollback also failed: {rollback}"))
                .unwrap_or_default();
            self.as_mut().set_status_message(qstring(format!(
                "Could not start list-column settings writer: {error}.{rollback}"
            )));
            return false;
        }
        true
    }

    pub fn apply_box_size(mut self: Pin<&mut Self>, box_size: f64) -> bool {
        let box_size = match BoxSize::new(box_size) {
            Ok(box_size) => box_size,
            Err(error) => {
                self.as_mut()
                    .set_status_message(qstring(format!("Could not apply box size: {error}")));
                return false;
            }
        };
        let previous = *self.as_ref().box_size();
        if previous == box_size.value() {
            return true;
        }
        let launchbox_root = self.as_ref().rust().launchbox_root.clone();
        if launchbox_root.is_some() && !self.as_mut().begin_library_mutation() {
            return false;
        }
        self.as_mut().set_box_size(box_size.value());
        let Some(root) = launchbox_root else {
            self.as_mut()
                .set_status_message(qstring("Applied box size for this session."));
            return true;
        };

        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut()
            .set_status_message(qstring("Saving LaunchBox box size in the background..."));
        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-box-size-settings-write".to_string())
            .spawn(move || {
                let result = write_box_size_setting(root, box_size);
                qt_thread
                    .queue(move |mut controller| {
                        controller
                            .as_mut()
                            .finish_box_size_write(generation, previous, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut().set_box_size(previous);
            self.as_mut().set_status_message(qstring(format!(
                "Could not start box-size settings writer: {error}"
            )));
            return false;
        }
        true
    }

    pub fn select_random_game(mut self: Pin<&mut Self>, avoid_game_id: QString) -> i32 {
        let avoid_game_id = avoid_game_id.to_string();
        let counter = self
            .as_ref()
            .rust()
            .random_selection_counter
            .wrapping_add(1);
        self.as_mut().rust_mut().random_selection_counter = counter;
        let clock_entropy = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs().rotate_left(17) ^ u64::from(duration.subsec_nanos()))
            .unwrap_or_default();
        let row = {
            let this = self.as_ref();
            let rust = this.rust();
            select_random_filtered_row(
                &rust.games,
                &rust.filtered_indices,
                (!avoid_game_id.is_empty()).then_some(avoid_game_id.as_str()),
                clock_entropy ^ counter.wrapping_mul(0x9e37_79b9_7f4a_7c15),
            )
        };
        let Some(row) = row else {
            self.as_mut().set_status_message(qstring(
                "No visible game is available for random selection.",
            ));
            return -1;
        };
        let title = self
            .as_ref()
            .filtered_game(saturating_i32(row))
            .map(|game| game.title.clone());
        if let Some(title) = title {
            self.as_mut()
                .set_status_message(qstring(format!("Random selection: {title}")));
        }
        saturating_i32(row)
    }

    pub fn big_box_star_rating_at(&self, row: i32, game_id: QString) -> f64 {
        let game_id = game_id.to_string();
        self.filtered_game(row)
            .filter(|game| game.id == game_id)
            .map(|game| game.star_rating_float)
            .unwrap_or_default()
    }

    pub fn update_big_box_game_state(
        mut self: Pin<&mut Self>,
        row: i32,
        game_id: QString,
        favorite: bool,
        star_rating: f64,
    ) -> bool {
        if !self.as_mut().begin_library_mutation() {
            return false;
        }
        let (_, star_rating) = match normalize_big_box_star_rating(star_rating) {
            Ok(rating) => rating,
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not update BigBox game state: {error}."
                )));
                return false;
            }
        };
        let game_id = game_id.to_string();
        let Some((source, root)) = self.as_ref().edit_target(row, &game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return false;
        };
        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut().set_status_message(qstring(
            "Saving BigBox favorite and star rating in the background...",
        ));

        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("bigbox-game-state-write".to_string())
            .spawn(move || {
                let result = write_big_box_game_state(root, source, game_id, favorite, star_rating);
                qt_thread
                    .queue(move |mut controller| {
                        controller
                            .as_mut()
                            .finish_big_box_game_state_write(generation, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut().set_status_message(qstring(format!(
                "Could not start BigBox game-state writer: {error}"
            )));
            return false;
        }
        true
    }

    pub fn big_box_playlist_action_json(&self, row: i32, game_id: QString) -> QString {
        if !self
            .rust()
            .big_box_game_action_policy
            .show_game_menu_playlist_actions
        {
            return QString::default();
        }
        let game_id = game_id.to_string();
        let Some(game) = self.filtered_game(row).filter(|game| game.id == game_id) else {
            return QString::default();
        };
        let payload = big_box_playlist_action_payload(
            &game.id,
            self.rust().playlist_filter.as_deref(),
            &self.rust().navigation_catalog,
        );
        serde_json::to_string(&payload)
            .map(qstring)
            .unwrap_or_default()
    }

    pub fn update_big_box_playlist_membership(
        mut self: Pin<&mut Self>,
        row: i32,
        game_id: QString,
        playlist_id: QString,
        present: bool,
    ) -> bool {
        if !self.as_mut().begin_library_mutation() {
            return false;
        }
        if !self
            .as_ref()
            .rust()
            .big_box_game_action_policy
            .show_game_menu_playlist_actions
        {
            self.as_mut().set_status_message(qstring(
                "BigBox playlist game actions are disabled in settings.",
            ));
            return false;
        }
        let game_id = game_id.to_string();
        let Some(game) = self
            .as_ref()
            .filtered_game(row)
            .filter(|game| game.id == game_id)
            .cloned()
        else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return false;
        };
        let requested_playlist_id = playlist_id.to_string();
        let requested_playlist_id = requested_playlist_id.trim();
        let target = self
            .as_ref()
            .rust()
            .navigation_catalog
            .playlists
            .iter()
            .find(|document| {
                document
                    .playlist
                    .id
                    .eq_ignore_ascii_case(requested_playlist_id)
            })
            .cloned();
        let Some(target) = target else {
            self.as_mut()
                .set_status_message(qstring("The selected playlist no longer exists."));
            return false;
        };
        if !is_manual_playlist_action_target(&target) {
            self.as_mut().set_status_message(qstring(
                "Auto-populated and auto-generated playlists do not accept manual game membership.",
            ));
            return false;
        }
        let already_present = target
            .games
            .iter()
            .any(|candidate| candidate.game_id.eq_ignore_ascii_case(&game.id));
        if already_present == present {
            self.as_mut().set_status_message(qstring(if present {
                "The selected game is already in that playlist."
            } else {
                "The selected game is no longer in that playlist."
            }));
            return false;
        }
        let Some(root) = self.as_ref().rust().library_root.clone() else {
            self.as_mut()
                .set_status_message(qstring("No writable library is loaded."));
            return false;
        };
        let source = target.source_path;
        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut().set_status_message(qstring(if present {
            "Adding the selected game to the playlist in the background..."
        } else {
            "Removing the selected game from the playlist in the background..."
        }));

        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("bigbox-playlist-membership-write".to_string())
            .spawn(move || {
                let result = write_big_box_playlist_membership(root, source, game, present);
                qt_thread
                    .queue(move |mut controller| {
                        controller
                            .as_mut()
                            .finish_big_box_playlist_membership_write(generation, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut().set_status_message(qstring(format!(
                "Could not start BigBox playlist writer: {error}"
            )));
            return false;
        }
        true
    }

    pub fn save_game(mut self: Pin<&mut Self>, row: i32, game_id: QString, edit_payload: QString) {
        if self.as_ref().library_operation_active() {
            self.as_mut()
                .set_status_message(qstring("Wait for the current library operation to finish."));
            return;
        }
        if *self.as_ref().pending_recovery_count() > 0 {
            self.as_mut().set_status_message(qstring(
                "Recover the interrupted transaction before editing this library.",
            ));
            return;
        }
        if *self.as_ref().write_conflict() {
            self.as_mut().set_status_message(qstring(
                "Reload the library before retrying an edit after a write conflict.",
            ));
            return;
        }
        let edit = match parse_game_edit_payload(&edit_payload.to_string()) {
            Ok(edit) => edit,
            Err(error) => {
                self.as_mut()
                    .set_status_message(qstring(format!("Could not save game: {error}.")));
                return;
            }
        };
        let title = edit.metadata.title.clone();

        let game_id = game_id.to_string();
        let Some((source, root)) = self.edit_target(row, &game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        };
        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut()
            .set_status_message(qstring(format!("Saving {title} in the background...")));

        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-game-write".to_string())
            .spawn(move || {
                let result = write_game(root, source, game_id, edit);
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_game_write(generation, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut()
                .set_status_message(qstring(format!("Could not start game writer: {error}")));
        }
    }

    pub fn add_additional_application(
        mut self: Pin<&mut Self>,
        row: i32,
        game_id: QString,
        edit_payload: QString,
    ) {
        if !self.as_mut().begin_library_mutation() {
            return;
        }
        let mut payload = match parse_additional_application_edit_payload(&edit_payload.to_string())
        {
            Ok(payload) => payload,
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not add additional application: {error}."
                )));
                return;
            }
        };
        if let Err(error) = canonicalize_additional_application_emulator(
            &mut payload.application,
            self.as_ref().rust().emulator_configuration.as_ref(),
            None,
        ) {
            self.as_mut().set_status_message(qstring(format!(
                "Could not add additional application: {error}."
            )));
            return;
        }
        let game_id = game_id.to_string();
        let Some((source, root)) = self.as_ref().edit_target(row, &game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        };
        let name = payload.application.name.clone();
        let request = AdditionalApplicationWriteRequest::Create {
            id: Uuid::new_v4().to_string(),
            edit: payload.application,
        };
        self.as_mut().start_additional_application_write(
            root,
            source,
            game_id,
            request,
            format!("Adding {name} in the background..."),
        );
    }

    pub fn save_additional_application(
        mut self: Pin<&mut Self>,
        row: i32,
        game_id: QString,
        application_id: QString,
        edit_payload: QString,
    ) {
        if !self.as_mut().begin_library_mutation() {
            return;
        }
        let game_id = game_id.to_string();
        let application_id = application_id.to_string();
        let existing = self
            .as_ref()
            .additional_applications_for_model(row, &game_id)
            .and_then(|applications| {
                applications
                    .iter()
                    .find(|application| application.id == application_id)
            })
            .cloned();
        let Some(existing) = existing else {
            self.as_mut().set_status_message(qstring(
                "The selected additional application no longer matches this game; reload and try again.",
            ));
            return;
        };
        let mut payload = match parse_additional_application_edit_payload(&edit_payload.to_string())
        {
            Ok(payload) => payload,
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not save additional application: {error}."
                )));
                return;
            }
        };
        if let Err(error) = canonicalize_additional_application_emulator(
            &mut payload.application,
            self.as_ref().rust().emulator_configuration.as_ref(),
            existing.emulator_id.as_deref(),
        ) {
            self.as_mut().set_status_message(qstring(format!(
                "Could not save additional application: {error}."
            )));
            return;
        }
        let Some((source, root)) = self.as_ref().edit_target(row, &game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        };
        let name = payload.application.name.clone();
        let request = AdditionalApplicationWriteRequest::Edit {
            id: application_id,
            edit: payload.application,
        };
        self.as_mut().start_additional_application_write(
            root,
            source,
            game_id,
            request,
            format!("Saving {name} in the background..."),
        );
    }

