    pub fn game_combine_candidates(&self, row: i32, game_id: QString) -> QString {
        let game_id = game_id.to_string();
        let Some((source, _)) = self.edit_target(row, &game_id) else {
            return QString::default();
        };
        let Some(root_game) = self.rust().games.iter().find(|game| game.id == game_id) else {
            return QString::default();
        };
        let mut candidates = self
            .rust()
            .games
            .iter()
            .zip(&self.rust().game_sources)
            .filter(|(game, game_source)| {
                game.id != root_game.id
                    && **game_source == source
                    && game.platform.eq_ignore_ascii_case(&root_game.platform)
            })
            .map(|(game, _)| GameCombineCandidate {
                id: game.id.clone(),
                title: game.title.clone(),
                platform: game.platform.clone(),
                application_path: game.application_path.clone(),
            })
            .collect::<Vec<_>>();
        candidates.sort_by(|left, right| {
            left.title
                .to_lowercase()
                .cmp(&right.title.to_lowercase())
                .then_with(|| left.id.cmp(&right.id))
        });
        serde_json::to_string(&candidates)
            .map(qstring)
            .unwrap_or_default()
    }

    pub fn combine_games(
        mut self: Pin<&mut Self>,
        row: i32,
        root_game_id: QString,
        selected_game_ids_json: QString,
    ) {
        if !self.as_mut().begin_library_mutation() {
            return;
        }
        let root_game_id = root_game_id.to_string();
        let Some((source, _)) = self.as_ref().edit_target(row, &root_game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected root game no longer matches this model; reload and try again.",
            ));
            return;
        };
        let Some(root) = self.as_ref().rust().launchbox_root.clone() else {
            self.as_mut().set_status_message(qstring(
                "Combining games requires a loaded LaunchBox directory so cross-document references can be migrated atomically.",
            ));
            return;
        };
        let requested =
            match serde_json::from_str::<Vec<String>>(&selected_game_ids_json.to_string()) {
                Ok(requested) => requested,
                Err(error) => {
                    self.as_mut().set_status_message(qstring(format!(
                        "The game selection is invalid: {error}"
                    )));
                    return;
                }
            };
        let mut selected_keys = requested
            .iter()
            .map(|id| id.to_lowercase())
            .collect::<BTreeSet<_>>();
        selected_keys.insert(root_game_id.to_lowercase());
        if selected_keys.len() < 2 {
            self.as_mut().set_status_message(qstring(
                "Select at least one other game to combine with the root.",
            ));
            return;
        }
        let mut selected_game_ids = Vec::with_capacity(selected_keys.len());
        selected_game_ids.push(root_game_id.clone());
        for key in selected_keys
            .iter()
            .filter(|key| !key.eq_ignore_ascii_case(&root_game_id))
        {
            let selected_id = {
                let this = self.as_ref();
                let rust = this.rust();
                rust.games
                    .iter()
                    .zip(&rust.game_sources)
                    .find(|(game, game_source)| {
                        game.id.eq_ignore_ascii_case(key) && **game_source == source
                    })
                    .map(|(game, _)| game.id.clone())
            };
            let Some(selected_id) = selected_id else {
                self.as_mut().set_status_message(qstring(format!(
                    "Selected game is no longer available in the root platform: {key}"
                )));
                return;
            };
            selected_game_ids.push(selected_id);
        }

        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut().set_status_message(qstring(format!(
            "Combining {} games and migrating their references...",
            selected_game_ids.len()
        )));
        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-game-combine".to_string())
            .spawn(move || {
                let result =
                    combine_games_in_library(root, source, root_game_id, selected_game_ids);
                qt_thread
                    .queue(move |mut controller| {
                        controller
                            .as_mut()
                            .finish_game_grouping_write(generation, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut()
                .set_status_message(qstring(format!("Could not start game combine: {error}")));
        }
    }

    pub fn expand_game_versions(mut self: Pin<&mut Self>, row: i32, game_id: QString) {
        if !self.as_mut().begin_library_mutation() {
            return;
        }
        let game_id = game_id.to_string();
        let Some((source, _)) = self.as_ref().edit_target(row, &game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        };
        let Some(root) = self.as_ref().rust().launchbox_root.clone() else {
            self.as_mut().set_status_message(qstring(
                "Expanding game versions requires a loaded LaunchBox directory.",
            ));
            return;
        };
        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_writing(true);
        self.as_mut()
            .set_status_message(qstring("Expanding launchable versions into games..."));
        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-game-expand".to_string())
            .spawn(move || {
                let result = expand_game_versions_in_library(root, source, game_id);
                qt_thread
                    .queue(move |mut controller| {
                        controller
                            .as_mut()
                            .finish_game_grouping_write(generation, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut()
                .set_status_message(qstring(format!("Could not start game expansion: {error}")));
        }
    }

    pub fn delete_game(mut self: Pin<&mut Self>, row: i32, game_id: QString) {
        if !self.as_mut().begin_library_mutation() {
            return;
        }
        let game_id = game_id.to_string();
        let Some((source, root)) = self.as_ref().edit_target(row, &game_id) else {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        };
        let reference_scope = PathBuf::from(self.as_ref().library_path().to_string());
        let generation = self.as_ref().rust().request_generation;
        self.as_mut().set_delete_blocker_count(0);
        self.as_mut().set_delete_blocker_summary(QString::default());
        self.as_mut().set_writing(true);
        self.as_mut().set_status_message(qstring(format!(
            "Checking references before deleting {game_id}..."
        )));

        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-game-delete".to_string())
            .spawn(move || {
                let result = delete_game_from_platform(root, reference_scope, source, game_id);
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_game_delete(generation, result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut()
                .set_status_message(qstring(format!("Could not start game delete: {error}")));
        }
    }

    pub fn launch_game(mut self: Pin<&mut Self>, row: i32, game_id: QString) {
        if self.as_ref().library_operation_active() || *self.as_ref().launch_session_active() {
            self.as_mut()
                .set_status_message(qstring("Wait for the current library operation to finish."));
            return;
        }
        if *self.as_ref().pending_recovery_count() > 0 {
            self.as_mut().set_status_message(qstring(
                "Recover the interrupted transaction before launching from this library.",
            ));
            return;
        }
        let game_id = game_id.to_string();
        let Some(game) = self.as_ref().filtered_game(row).cloned() else {
            self.as_mut().set_status_message(qstring(
                "The selected game is no longer present; reload and try again.",
            ));
            return;
        };
        if game.id != game_id {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        }
        let automatic_applications = self
            .as_ref()
            .rust()
            .additional_applications_by_game
            .get(&game.id)
            .cloned()
            .unwrap_or_default();
        self.as_mut().start_launch(
            game,
            LaunchSelection::MainGame {
                automatic_applications,
            },
        );
    }

    pub fn launch_additional_application(
        mut self: Pin<&mut Self>,
        row: i32,
        game_id: QString,
        application_id: QString,
    ) {
        if self.as_ref().library_operation_active() || *self.as_ref().launch_session_active() {
            self.as_mut()
                .set_status_message(qstring("Wait for the current launch operation to finish."));
            return;
        }
        if *self.as_ref().pending_recovery_count() > 0 {
            self.as_mut().set_status_message(qstring(
                "Recover the interrupted transaction before launching from this library.",
            ));
            return;
        }
        let game_id = game_id.to_string();
        let application_id = application_id.to_string();
        let Some(game) = self.as_ref().filtered_game(row).cloned() else {
            self.as_mut().set_status_message(qstring(
                "The selected game is no longer present; reload and try again.",
            ));
            return;
        };
        if game.id != game_id {
            self.as_mut().set_status_message(qstring(
                "The selected game no longer matches this model; reload and try again.",
            ));
            return;
        }
        let application = self
            .as_ref()
            .rust()
            .additional_applications_by_game
            .get(&game.id)
            .and_then(|applications| {
                applications
                    .iter()
                    .find(|application| application.id == application_id)
            })
            .cloned();
        let Some(application) = application else {
            self.as_mut().set_status_message(qstring(
                "The selected additional application is no longer present; reload and try again.",
            ));
            return;
        };
        self.as_mut().start_launch(
            game,
            LaunchSelection::AdditionalApplication(Box::new(application)),
        );
    }

    fn start_launch(mut self: Pin<&mut Self>, game: Game, selection: LaunchSelection) {
        let (
            root,
            source,
            configuration,
            path_resolver,
            mounts,
            frontend_policy,
            frontend_pause_policy,
        ) = {
            let this = self.as_ref();
            let rust = this.rust();
            let Some(root) = rust.launchbox_root.clone() else {
                self.as_mut().set_status_message(qstring(
                    "Load a LaunchBox directory, not a standalone platform XML file, before launching games.",
                ));
                return;
            };
            let Some(source) = rust
                .games
                .iter()
                .position(|candidate| candidate.id == game.id)
                .and_then(|index| rust.game_sources.get(index))
                .cloned()
            else {
                self.as_mut().set_status_message(qstring(
                    "The selected game's platform document is unavailable; reload and try again.",
                ));
                return;
            };
            (
                root,
                source,
                rust.emulator_configuration.clone(),
                rust.path_resolver.clone(),
                rust.mounts_by_game
                    .get(&game.id)
                    .cloned()
                    .unwrap_or_default(),
                if *this.frontend_is_big_box() {
                    rust.big_box_launch_screen_policy.clone()
                } else {
                    rust.launchbox_launch_screen_policy.clone()
                },
                if *this.frontend_is_big_box() {
                    rust.big_box_pause_screen_policy.clone()
                } else {
                    rust.launchbox_pause_screen_policy.clone()
                },
            )
        };
        let generation = self.as_ref().rust().request_generation;
        let title = game.title.clone();
        self.as_mut().set_launching(true);
        self.as_mut().set_launch_session_active(true);
        self.as_mut().set_startup_screen_active(false);
        self.as_mut().set_startup_screen_primary_started(false);
        self.as_mut().set_startup_screen_delay_ms(0);
        self.as_mut()
            .set_startup_screen_game_title(QString::default());
        self.as_mut()
            .set_startup_screen_settings_source(QString::default());
        self.as_mut().set_shutdown_screen_active(false);
        self.as_mut()
            .set_shutdown_screen_game_title(QString::default());
        self.as_mut()
            .set_shutdown_screen_settings_source(QString::default());
        self.as_mut().set_pause_screen_available(false);
        self.as_mut().set_pause_screen_active(false);
        self.as_mut().set_pause_screen_process_suspended(false);
        self.as_mut().set_pause_screen_forceful_activation(false);
        self.as_mut()
            .set_pause_screen_game_title(QString::default());
        self.as_mut()
            .set_pause_screen_settings_source(QString::default());
        self.as_mut().set_last_launch_succeeded(false);
        self.as_mut().set_last_launch_game_id(QString::default());
        self.as_mut().set_last_launch_target_id(QString::default());
        {
            let mut rust = self.as_mut().rust_mut();
            rust.session_stats_writes = 0;
            rust.session_stats_error = None;
            rust.startup_screen_presentations = 0;
            rust.startup_screen_timer_dismissals = 0;
            rust.shutdown_screen_presentations = 0;
            rust.shutdown_screen_timer_dismissals = 0;
            rust.pause_screen_presentations = 0;
            rust.pause_process_suspensions = 0;
            rust.pause_process_resumptions = 0;
            rust.delegated_session_completions = 0;
            rust.pending_shutdown_screen = None;
        }
        let (launch_control_sender, launch_control_receiver) = mpsc::channel();
        self.as_mut().rust_mut().launch_control_sender = Some(launch_control_sender);
        self.as_mut()
            .set_status_message(qstring(format!("Launching {title} in the background...")));

        let qt_thread = self.as_ref().qt_thread();
        let event_thread = qt_thread.clone();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-game-launch".to_string())
            .spawn(move || {
                let archive_extractor = ArchiveExtractor::for_launchbox_root(&root);
                let sequence = std::env::current_exe()
                    .map_err(|error| {
                        format!(
                            "could not locate the running frontend executable: {error}"
                        )
                    })
                    .and_then(|frontend_executable| {
                        let context = LaunchContext {
                            frontend_executable: Some(frontend_executable),
                        };
                        match &selection {
                            LaunchSelection::MainGame {
                                automatic_applications,
                            } => prepare_game_launch_sequence_with_mounts_context_and_resolver(
                                &root,
                                &game,
                                automatic_applications,
                                &mounts,
                                configuration.as_ref(),
                                &context,
                                &path_resolver,
                                &archive_extractor,
                            ),
                            LaunchSelection::AdditionalApplication(application) => {
                                prepare_selected_additional_application_sequence_with_mounts_context_and_resolver(
                                    &root,
                                    &game,
                                    application,
                                    &mounts,
                                    configuration.as_ref(),
                                    &context,
                                    &path_resolver,
                                    &archive_extractor,
                                )
                            }
                        }
                        .map_err(|error| error.to_string())
                    });

                let mut primary_started = false;
                let mut shutdown = LaunchShutdownPolicy::disabled();
                let mut shutdown_title = title.clone();
                let mut session_stats_errors = Vec::new();
                let result = sequence.and_then(|mut sequence| {
                    let startup = LaunchStartupPolicy {
                        enabled: frontend_policy.enabled && sequence.startup.enabled,
                        ..sequence.startup
                    };
                    shutdown = LaunchShutdownPolicy {
                        enabled: frontend_policy.enabled && sequence.shutdown.enabled,
                        ..sequence.shutdown
                    };
                    sequence.pause.enabled =
                        frontend_pause_policy.enabled && sequence.pause.enabled;
                    shutdown_title.clone_from(&sequence.game_title);
                    let startup_title = sequence.game_title.clone();
                    let pause_title = sequence.game_title.clone();
                    let pause = sequence.pause;
                    event_thread
                        .queue(move |mut controller| {
                            controller
                                .as_mut()
                                .begin_pause_session(generation, pause_title, pause);
                        })
                        .map_err(|error| {
                            format!("could not configure the pause screen: {error}")
                        })?;
                    event_thread
                        .queue(move |mut controller| {
                            controller.as_mut().begin_startup_screen(
                                generation,
                                startup_title,
                                startup,
                            );
                        })
                        .map_err(|error| {
                            format!("could not present the startup screen: {error}")
                        })?;
                    if startup.enabled && !startup.load_delay.is_zero() {
                        std::thread::sleep(startup.load_delay);
                    }
                    let template = primary_launch_template(&sequence)?;
                    let report = execute_launch_sequence_controlled(
                        &sequence,
                        &launch_control_receiver,
                        |event| match event {
                        LaunchSequenceEvent::StepStarted {
                            role,
                            target,
                            pid,
                            started_at,
                            ..
                        } if role.is_primary() => {
                            primary_started = true;
                            let mut success = template.clone();
                            success.pid = pid;
                            event_thread
                                .queue(move |mut controller| {
                                    controller
                                        .as_mut()
                                        .finish_game_launch(generation, Ok(success));
                                })
                                .ok();

                            let stats_result = write_play_session_start(
                                root.clone(),
                                source.clone(),
                                &target,
                                &game.id,
                                started_at,
                            );
                            if let Err(error) = &stats_result {
                                session_stats_errors.push(describe_game_write_failure(error));
                            }
                            event_thread
                                .queue(move |mut controller| {
                                    controller
                                        .as_mut()
                                        .finish_play_session_stats(generation, stats_result);
                                })
                                .ok();
                        }
                        LaunchSequenceEvent::BeforeWaitTimedOut { target, timeout } => {
                            eprintln!(
                                "Before-app {target:?} exceeded its {:.0}s wait ceiling; continuing.",
                                timeout.as_secs_f64()
                            );
                        }
                        LaunchSequenceEvent::PrimaryPaused { process_suspended } => {
                            event_thread
                                .queue(move |mut controller| {
                                    controller.as_mut().finish_pause_transition(
                                        generation,
                                        true,
                                        process_suspended,
                                    );
                                })
                                .ok();
                        }
                        LaunchSequenceEvent::PrimaryResumed { process_resumed } => {
                            event_thread
                                .queue(move |mut controller| {
                                    controller.as_mut().finish_pause_transition(
                                        generation,
                                        false,
                                        process_resumed,
                                    );
                                })
                                .ok();
                        }
                        LaunchSequenceEvent::PrimaryControlFailed { action, message } => {
                            event_thread
                                .queue(move |mut controller| {
                                    controller.as_mut().finish_pause_control_failure(
                                        generation, action, message,
                                    );
                                })
                                .ok();
                        }
                        _ => {}
                    },
                    )
                    .map_err(|error| error.to_string())?;

                    if report.primary_runtime.as_secs() > 0 {
                        let stats_result = write_play_session_time(
                            root.clone(),
                            source.clone(),
                            &report.primary_target,
                            &report.game_id,
                            report.primary_runtime,
                        );
                        if let Err(error) = &stats_result {
                            session_stats_errors.push(describe_game_write_failure(error));
                        }
                        event_thread
                            .queue(move |mut controller| {
                                controller
                                    .as_mut()
                                    .finish_play_session_stats(generation, stats_result);
                            })
                            .ok();
                    }
                    Ok(report)
                });
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_launch_session(
                            generation,
                            result,
                            primary_started,
                            shutdown_title,
                            shutdown,
                            session_stats_errors,
                        );
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().rust_mut().launch_control_sender = None;
            self.as_mut().set_launching(false);
            self.as_mut().set_launch_session_active(false);
            self.as_mut().set_startup_screen_active(false);
            self.as_mut().set_startup_screen_primary_started(false);
            self.as_mut().set_shutdown_screen_active(false);
            self.as_mut().set_pause_screen_available(false);
            self.as_mut().set_pause_screen_active(false);
            self.as_mut().set_pause_screen_process_suspended(false);
            self.as_mut()
                .set_status_message(qstring(format!("Could not start game launcher: {error}")));
        }
    }

    fn begin_pause_session(
        mut self: Pin<&mut Self>,
        generation: u64,
        game_title: String,
        pause: LaunchPausePolicy,
    ) {
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        self.as_mut().set_pause_screen_available(pause.enabled);
        self.as_mut().set_pause_screen_active(false);
        self.as_mut().set_pause_screen_process_suspended(false);
        self.as_mut()
            .set_pause_screen_forceful_activation(pause.forceful_activation);
        self.as_mut()
            .set_pause_screen_game_title(qstring(game_title));
        self.as_mut()
            .set_pause_screen_settings_source(qstring(pause.source.label()));
    }

    pub fn pause_launch_session(mut self: Pin<&mut Self>) {
        if !*self.as_ref().pause_screen_available()
            || !*self.as_ref().launch_session_active()
            || *self.as_ref().pause_screen_active()
        {
            return;
        }
        let result = self
            .as_ref()
            .rust()
            .launch_control_sender
            .as_ref()
            .ok_or_else(|| "the launch worker is no longer available".to_string())
            .and_then(|sender| {
                sender
                    .send(LaunchControlCommand::Pause)
                    .map_err(|error| error.to_string())
            });
        match result {
            Ok(()) => self
                .as_mut()
                .set_status_message(qstring("Pausing the active game session...")),
            Err(error) => self
                .as_mut()
                .set_status_message(qstring(format!("Could not pause the game: {error}"))),
        }
    }

    pub fn resume_launch_session(mut self: Pin<&mut Self>) {
        if !*self.as_ref().pause_screen_active() {
            return;
        }
        let result = self
            .as_ref()
            .rust()
            .launch_control_sender
            .as_ref()
            .ok_or_else(|| "the launch worker is no longer available".to_string())
            .and_then(|sender| {
                sender
                    .send(LaunchControlCommand::Resume)
                    .map_err(|error| error.to_string())
            });
        match result {
            Ok(()) => self
                .as_mut()
                .set_status_message(qstring("Resuming the active game session...")),
            Err(error) => self
                .as_mut()
                .set_status_message(qstring(format!("Could not resume the game: {error}"))),
        }
    }

    fn finish_pause_transition(
        mut self: Pin<&mut Self>,
        generation: u64,
        paused: bool,
        process_transitioned: bool,
    ) {
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        if paused {
            self.as_mut()
                .set_pause_screen_process_suspended(process_transitioned);
            self.as_mut().set_pause_screen_active(true);
            {
                let mut rust = self.as_mut().rust_mut();
                rust.pause_screen_presentations = rust.pause_screen_presentations.saturating_add(1);
                if process_transitioned {
                    rust.pause_process_suspensions =
                        rust.pause_process_suspensions.saturating_add(1);
                }
            }
            self.as_mut()
                .set_status_message(qstring("The active game session is paused."));
        } else {
            self.as_mut().set_pause_screen_active(false);
            self.as_mut().set_pause_screen_process_suspended(false);
            if process_transitioned {
                self.as_mut().rust_mut().pause_process_resumptions = self
                    .as_ref()
                    .rust()
                    .pause_process_resumptions
                    .saturating_add(1);
            }
            self.as_mut()
                .set_status_message(qstring("The active game session resumed."));
        }
    }

    fn finish_pause_control_failure(
        mut self: Pin<&mut Self>,
        generation: u64,
        action: LaunchControlCommand,
        message: String,
    ) {
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        let action = match action {
            LaunchControlCommand::Pause => "pause",
            LaunchControlCommand::Resume => "resume",
        };
        self.as_mut().set_status_message(qstring(format!(
            "Could not {action} the active game process: {message}"
        )));
    }

    fn begin_startup_screen(
        mut self: Pin<&mut Self>,
        generation: u64,
        game_title: String,
        startup: LaunchStartupPolicy,
    ) {
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        self.as_mut().set_startup_screen_primary_started(false);
        self.as_mut()
            .set_startup_screen_delay_ms(duration_millis_i32(startup.load_delay));
        self.as_mut()
            .set_startup_screen_game_title(qstring(game_title));
        self.as_mut()
            .set_startup_screen_settings_source(qstring(startup.source.label()));
        self.as_mut().set_startup_screen_active(startup.enabled);
        if startup.enabled {
            self.as_mut().rust_mut().startup_screen_presentations = self
                .as_ref()
                .rust()
                .startup_screen_presentations
                .saturating_add(1);
        }
    }

    pub fn dismiss_startup_screen(mut self: Pin<&mut Self>) {
        if !*self.as_ref().startup_screen_active()
            || !*self.as_ref().startup_screen_primary_started()
        {
            return;
        }
        self.as_mut().set_startup_screen_active(false);
        self.as_mut().set_startup_screen_primary_started(false);
        self.as_mut().rust_mut().startup_screen_timer_dismissals = self
            .as_ref()
            .rust()
            .startup_screen_timer_dismissals
            .saturating_add(1);
        let pending_shutdown = self.as_mut().rust_mut().pending_shutdown_screen.take();
        if let Some((game_title, shutdown)) = pending_shutdown {
            self.as_mut().present_shutdown_screen(game_title, shutdown);
        }
    }

    pub fn dismiss_shutdown_screen(mut self: Pin<&mut Self>) {
        if !*self.as_ref().shutdown_screen_active() {
            return;
        }
        self.as_mut().set_shutdown_screen_active(false);
        self.as_mut().rust_mut().shutdown_screen_timer_dismissals = self
            .as_ref()
            .rust()
            .shutdown_screen_timer_dismissals
            .saturating_add(1);
    }

    fn present_shutdown_screen(
        mut self: Pin<&mut Self>,
        game_title: String,
        shutdown: LaunchShutdownPolicy,
    ) {
        debug_assert!(shutdown.enabled);
        self.as_mut()
            .set_shutdown_screen_game_title(qstring(game_title));
        self.as_mut()
            .set_shutdown_screen_settings_source(qstring(shutdown.source.label()));
        self.as_mut().set_shutdown_screen_active(true);
        self.as_mut().rust_mut().shutdown_screen_presentations = self
            .as_ref()
            .rust()
            .shutdown_screen_presentations
            .saturating_add(1);
    }

    pub fn dismiss_delete_blocker(mut self: Pin<&mut Self>) {
        self.as_mut().set_delete_blocker_count(0);
        self.as_mut().set_delete_blocker_summary(QString::default());
    }

    pub fn recover_pending_changes(mut self: Pin<&mut Self>) {
        if self.as_ref().library_operation_active() {
            self.as_mut()
                .set_status_message(qstring("Wait for the current library operation to finish."));
            return;
        }
        if *self.as_ref().pending_recovery_count() == 0 {
            self.as_mut().set_status_message(qstring(
                "This library has no pending transaction to recover.",
            ));
            return;
        }
        let Some(root) = self.as_ref().rust().library_root.clone() else {
            self.as_mut()
                .set_status_message(qstring("No writable library root is loaded."));
            return;
        };

        self.as_mut().set_writing(true);
        self.as_mut()
            .set_status_message(qstring("Recovering the interrupted transaction..."));
        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("launchbox-transaction-recovery".to_string())
            .spawn(move || {
                let result = recover_pending_transactions(&root)
                    .map(|reports| reports.len())
                    .map_err(|error| error.to_string());
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_recovery(result);
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_writing(false);
            self.as_mut().set_status_message(qstring(format!(
                "Could not start transaction recovery: {error}"
            )));
        }
    }

    pub fn reload_library(mut self: Pin<&mut Self>) {
        let path = self.as_ref().library_path().clone();
        if path.is_empty() {
            self.as_mut()
                .set_status_message(qstring("No user library is loaded."));
            return;
        }
        self.as_mut().load_library(path);
    }

