    pub fn report_supplemental_media_smoke_success(
        &self,
        frontend: QString,
        game_id: QString,
        manual_url: QString,
        first_music_url: QString,
        second_music_url: QString,
    ) -> bool {
        let frontend = frontend.to_string();
        let game_id = game_id.to_string();
        let Some(expected_manual) = self.rust().manual_paths_by_game_id.get(&game_id) else {
            return false;
        };
        let Some(expected_tracks) = self.rust().music_paths_by_game_id.get(&game_id) else {
            return false;
        };
        let local_path = |value: &QString| {
            QUrl::from_user_input(value, &QString::default())
                .to_local_file()
                .map(|path| PathBuf::from(path.to_string()))
        };
        let Some(manual_file) = local_path(&manual_url) else {
            return false;
        };
        let Some(first_music_file) = local_path(&first_music_url) else {
            return false;
        };
        let Some(second_music_file) = local_path(&second_music_url) else {
            return false;
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let policy_matches = match frontend.as_str() {
            "launchbox" => {
                !*self.launchbox_auto_play_music()
                    && *self.launchbox_shuffle_music()
                    && !*self.big_box_auto_play_music_games_list()
                    && !*self.big_box_auto_play_music_game_details()
            }
            "bigbox" => {
                !*self.big_box_auto_play_music_games_list()
                    && !*self.big_box_auto_play_music_game_details()
                    && !*self.big_box_prioritize_music_over_video_audio()
                    && !*self.big_box_repeat_game_music()
                    && !*self.big_box_shuffle_soundtrack_music()
                    && *self.big_box_show_game_menu_play_music()
                    && *self.big_box_show_game_menu_view_manual()
                    && *self.big_box_music_volume_percent() == 75
            }
            _ => false,
        };
        let success = game_id == "fixture-adventure"
            && self.rust().manual_paths_by_game_id.len() == 1
            && *self.indexed_manual_count() == 1
            && *self.indexed_music_track_count() == 2
            && expected_tracks.len() == 2
            && manual_file == *expected_manual
            && first_music_file == expected_tracks[0]
            && second_music_file == expected_tracks[1]
            && manual_file.file_name().and_then(|name| name.to_str())
                == Some("fixture-adventure.pdf")
            && first_music_file.file_name().and_then(|name| name.to_str())
                == Some("Fixture Adventure-01.mp3")
            && second_music_file.file_name().and_then(|name| name.to_str())
                == Some("Fixture Adventure-02.mp3")
            && safe_regular_file(&manual_file)
            && safe_regular_file(&first_music_file)
            && safe_regular_file(&second_music_file)
            && !*self.loading()
            && !*self.writing()
            && policy_matches;
        if success {
            let marker = if frontend == "launchbox" {
                "LAUNCHBOX_SUPPLEMENTAL_MEDIA_SMOKE_COMPLETE"
            } else {
                "BIGBOX_SUPPLEMENTAL_MEDIA_SMOKE_COMPLETE"
            };
            eprintln!(
                "{marker} id=fixture-adventure manuals=1 tracks=2 manual=pdf audio=mp3 playlist=m3u controls=1"
            );
        }
        success
    }

    pub fn report_background_music_smoke_success(
        &self,
        default_first_url: QString,
        platform_first_url: QString,
        playlist_first_url: QString,
        category_first_url: QString,
    ) -> bool {
        let expected = [
            ("", "", &default_first_url, "Default-01.mp3"),
            (
                "platform",
                "Fixture Console",
                &platform_first_url,
                "Platform-01.mp3",
            ),
            (
                "playlist",
                "Fixture Favorites",
                &playlist_first_url,
                "Playlist-01.mp3",
            ),
            (
                "category",
                "Fixture Category",
                &category_first_url,
                "Category-01.mp3",
            ),
        ];
        let local_path = |value: &QString| {
            QUrl::from_user_input(value, &QString::default())
                .to_local_file()
                .map(|path| PathBuf::from(path.to_string()))
        };
        let collections_match = expected.iter().all(|(kind, name, url, file_name)| {
            let Some((_, tracks)) = self.background_music_collection(kind, name) else {
                return false;
            };
            let Some(actual) = local_path(url) else {
                return false;
            };
            tracks.len() == 2
                && actual == tracks[0]
                && actual.file_name().and_then(|value| value.to_str()) == Some(*file_name)
                && fs::symlink_metadata(&actual)
                    .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        });
        let missing_context_falls_back = self
            .background_music_collection("platform", "No Such Fixture")
            .is_some_and(|(key, tracks)| {
                key == "default"
                    && tracks.len() == 2
                    && tracks.first().is_some_and(|path| {
                        path.file_name().and_then(|value| value.to_str()) == Some("Default-01.mp3")
                    })
            });
        let success = collections_match
            && missing_context_falls_back
            && *self.indexed_background_music_track_count() == 8
            && *self.big_box_background_music_enabled()
            && *self.big_box_background_music_volume_percent() == 63
            && *self.big_box_music_on_screen_display_enabled()
            && !*self.big_box_shuffle_background_music()
            && *self.big_box_context_specific_background_music()
            && !*self.loading()
            && !*self.writing();
        if success {
            let video_audio = u8::from(*self.big_box_play_video_audio_with_background_music());
            eprintln!(
                "BIGBOX_BACKGROUND_MUSIC_SMOKE_COMPLETE tracks=8 default=2 platform=2 playlist=2 category=2 audio=mp3 playlist_format=m3u controls=1 osd=1 video_audio={video_audio}"
            );
        }
        success
    }

    pub fn report_startup_video_smoke_success(
        &self,
        selected_url: QString,
        selected_index: i32,
        skipped: bool,
        ended_naturally: bool,
        probe_ready_before_load: bool,
    ) -> bool {
        let paths = &self.rust().startup_video_paths;
        let expected_names: &[&str] = match paths.len() {
            1 => &["Startup.mp4"],
            2 => &["Startup-01.mp4", "Startup-02.mp4"],
            _ => &[],
        };
        let selected_index_usize = usize::try_from(selected_index).ok();
        let selected_path = selected_index_usize.and_then(|index| paths.get(index));
        let selected_url = QUrl::from_user_input(&selected_url, &QString::default())
            .to_local_file()
            .map(|path| PathBuf::from(path.to_string()));
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let paths_match = !expected_names.is_empty()
            && paths
                .iter()
                .zip(expected_names)
                .all(|(path, expected_name)| {
                    path.file_name().and_then(|name| name.to_str()) == Some(*expected_name)
                        && safe_regular_file(path)
                });
        let success = paths_match
            && *self.indexed_startup_video_count() == saturating_i32(paths.len())
            && selected_path.is_some()
            && selected_url.as_ref() == selected_path
            && skipped != ended_naturally
            && *self.big_box_startup_video_volume_percent() == 61
            && probe_ready_before_load
            && *self.startup_presentation_ready()
            && !*self.loading()
            && !*self.writing();
        if success {
            let completion = if skipped { "skip" } else { "natural" };
            let selected_name = selected_path
                .and_then(|path| path.file_name())
                .and_then(|name| name.to_str())
                .unwrap_or_default();
            eprintln!(
                "BIGBOX_STARTUP_VIDEO_SMOKE_COMPLETE videos={} selected={selected_name} decode=h264 completion={completion} volume=61 probe_before_load=1",
                paths.len()
            );
        }
        success
    }

    pub fn report_startup_splash_smoke_success(
        &self,
        expected_enabled: bool,
        selected_sound_url: QString,
        selected_sound_index: i32,
        probe_ready_before_load: bool,
        splash_was_visible: bool,
        sound_played: bool,
    ) -> bool {
        let paths = &self.rust().startup_sound_paths;
        let expected_names: &[&str] = match paths.len() {
            1 => &["Startup.wav"],
            2 => &["STARTUP001.wav", "STARTUP002.wav"],
            _ => &[],
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let paths_match = !expected_names.is_empty()
            && paths
                .iter()
                .zip(expected_names)
                .all(|(path, expected_name)| {
                    path.file_name().and_then(|name| name.to_str()) == Some(*expected_name)
                        && safe_regular_file(path)
                });
        let selected_index_usize = usize::try_from(selected_sound_index).ok();
        let selected_path = selected_index_usize.and_then(|index| paths.get(index));
        let selected_url_text = selected_sound_url.to_string();
        let selected_url = if selected_url_text.trim().is_empty() {
            None
        } else {
            QUrl::from_user_input(&selected_sound_url, &QString::default())
                .to_local_file()
                .map(|path| PathBuf::from(path.to_string()))
        };
        let enabled_state_matches = if expected_enabled {
            *self.big_box_show_startup_splash_screen()
                && *self.big_box_play_startup_sound()
                && splash_was_visible
                && sound_played
                && selected_path.is_some()
                && selected_url.as_ref() == selected_path
        } else {
            !*self.big_box_show_startup_splash_screen()
                && !*self.big_box_play_startup_sound()
                && !splash_was_visible
                && !sound_played
                && selected_sound_index == -1
                && selected_url.is_none()
        };
        let success = paths_match
            && *self.indexed_startup_sound_count() == saturating_i32(paths.len())
            && *self.big_box_startup_sound_volume_percent() == 64
            && *self.big_box_master_volume_percent() == 50
            && self.big_box_sound_pack().to_string() == "Fixture Sounds"
            && probe_ready_before_load
            && *self.startup_presentation_ready()
            && enabled_state_matches
            && !*self.loading()
            && !*self.writing();
        if success {
            let selected_name = selected_path
                .and_then(|path| path.file_name())
                .and_then(|name| name.to_str())
                .unwrap_or("none");
            let enabled = u8::from(expected_enabled);
            let splash = u8::from(splash_was_visible);
            let audio = u8::from(sound_played);
            eprintln!(
                "BIGBOX_STARTUP_SPLASH_SMOKE_COMPLETE enabled={enabled} sounds={} selected={selected_name} decode=wav probe_before_load=1 splash={splash} audio={audio} volume=32",
                paths.len()
            );
        }
        success
    }

    pub fn report_big_box_attract_mode_smoke_success(
        &self,
        expected_enabled: bool,
        wheel_steps: i32,
        movement_cycles: i32,
        filter_switches: i32,
        automatic_delay_elapsed_ms: i32,
        manual_start_seen: bool,
        input_stop_count: i32,
        sound_ready: bool,
    ) -> bool {
        let paths = &self.rust().attract_move_sound_paths;
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let sounds_match = paths.len() == 2
            && paths
                .iter()
                .zip(["MOVE001.wav", "MOVE002.wav"])
                .all(|(path, expected_name)| {
                    path.file_name().and_then(|name| name.to_str()) == Some(expected_name)
                        && safe_regular_file(path)
                });
        let interaction_matches = if expected_enabled {
            wheel_steps >= saturating_i32(BIG_BOX_ATTRACT_MODE_WHEEL_STEPS as usize)
                && movement_cycles >= 1
                && filter_switches >= 1
                && (800..=5_000).contains(&automatic_delay_elapsed_ms)
                && input_stop_count >= 2
        } else {
            wheel_steps >= 1
                && movement_cycles == 0
                && filter_switches == 0
                && automatic_delay_elapsed_ms == 0
                && input_stop_count >= 1
        };
        let success = sounds_match
            && *self.indexed_attract_move_sound_count() == 2
            && *self.big_box_attract_mode_enabled() == expected_enabled
            && *self.big_box_attract_mode_switch_filters()
            && *self.big_box_attract_mode_delay_seconds() == 1
            && *self.big_box_attract_mode_time_per_movement_seconds() == 1
            && *self.big_box_attract_mode_maximum_speed_ms() == 20
            && *self.big_box_attract_mode_minimum_speed_ms() == 80
            && *self.big_box_play_move_in_attract_mode()
            && *self.big_box_attract_mode_navigation_sound_volume_percent() == 40
            && *self.big_box_attract_mode_master_volume_percent() == 50
            && self.big_box_attract_mode_wheel_step_count()
                == saturating_i32(BIG_BOX_ATTRACT_MODE_WHEEL_STEPS as usize)
            && self.big_box_attract_mode_wheel_interval_ms(0) == 80
            && self.big_box_attract_mode_wheel_interval_ms(7) == 20
            && manual_start_seen
            && sound_ready
            && interaction_matches
            && !*self.loading()
            && !*self.writing();
        if success {
            let enabled = u8::from(expected_enabled);
            eprintln!(
                "BIGBOX_ATTRACT_MODE_SMOKE_COMPLETE enabled={enabled} wheel_steps={wheel_steps} movement_cycles={movement_cycles} filter_switches={filter_switches} auto_delay_ms={automatic_delay_elapsed_ms} manual=1 input_exit={input_stop_count} sounds=2 sound=wav volume=20 curve=80-20-80"
            );
        }
        success
    }

