    pub fn report_big_box_marquee_smoke_success(
        &self,
        screen_count: i32,
        resolved_monitor_index: i32,
        game_id: QString,
        platform_name: QString,
        game_video_url: QString,
        game_image_url: QString,
        platform_banner_url: QString,
    ) -> bool {
        let game_id = game_id.to_string();
        let platform_name = platform_name.to_string();
        let expected_game = self.big_box_game_marquee_media(&game_id);
        let expected_platform = self.big_box_platform_marquee_media(&platform_name);
        let local_file = |value: QString| {
            QUrl::from_user_input(&value, &QString::default())
                .to_local_file()
                .map(|path| PathBuf::from(path.to_string()))
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let video = local_file(game_video_url);
        let image = local_file(game_image_url);
        let banner = local_file(platform_banner_url);
        let policy = &self.rust().big_box_marquee_policy;
        let success = screen_count >= 1
            && resolved_monitor_index == 0
            && game_id == "fixture-adventure"
            && platform_name == "Fixture Console"
            && expected_game.as_ref().is_some_and(|media| {
                video.as_ref() == media.video_path.as_ref()
                    && image.as_ref() == media.marquee_image_path.as_ref()
                    && media.has_direct_media()
            })
            && expected_platform.is_some_and(|media| banner.as_ref() == media.banner_path.as_ref())
            && video.as_deref().is_some_and(safe_regular_file)
            && image.as_deref().is_some_and(safe_regular_file)
            && banner.as_deref().is_some_and(safe_regular_file)
            && policy.primary_monitor_index == 0
            && policy.marquee_monitor_index == 0
            && policy.ignore_theme_views
            && policy.stretch_images
            && policy.compatibility_mode == BigBoxMarqueeCompatibilityMode::TopHalfCutOff
            && *self.big_box_primary_monitor_index() == 0
            && *self.big_box_marquee_monitor_index() == 0
            && *self.big_box_marquee_ignore_theme_views()
            && *self.big_box_marquee_stretch_images()
            && self.big_box_marquee_compatibility_mode().to_string() == "TopHalfCutOff"
            && *self.big_box_marquee_settings_revision() > 1
            && *self.big_box_platform_marquee_count() == 1
            && !*self.loading()
            && !*self.writing();
        if success {
            eprintln!(
                "BIGBOX_MARQUEE_SMOKE_COMPLETE screens={screen_count} monitor=0 game=fixture-adventure video=mp4 image=svg platform=Fixture Console banner=svg stretch=1 theme_override=1 compatibility=TopHalfCutOff transaction=1 revision={}",
                self.big_box_marquee_settings_revision()
            );
        } else {
            eprintln!(
                "BIGBOX_MARQUEE_SMOKE_INCOMPLETE screens={screen_count} resolved={resolved_monitor_index} game={game_id} platform={platform_name} video={video:?} image={image:?} banner={banner:?} policy={policy:?} platform_media={} revision={} loading={} writing={}",
                self.big_box_platform_marquee_count(),
                self.big_box_marquee_settings_revision(),
                self.loading(),
                self.writing()
            );
        }
        success
    }

    pub fn report_big_box_security_smoke_success(
        &self,
        initial_revision: i32,
        blocked_actions: i32,
        failed_unlocks: i32,
        successful_unlocks: i32,
    ) -> bool {
        let policy = &self.rust().big_box_security_policy;
        let expected_revision = initial_revision.wrapping_add(1);
        let counters_match = usize::try_from(blocked_actions)
            .is_ok_and(|count| self.rust().big_box_security_blocked_actions == count as u64)
            && usize::try_from(failed_unlocks)
                .is_ok_and(|count| self.rust().big_box_security_failed_unlocks == count as u64)
            && usize::try_from(successful_unlocks)
                .is_ok_and(|count| self.rust().big_box_security_successful_unlocks == count as u64);
        let success = policy.pin_configured()
            && policy.show_game_lock_unlock
            && policy.permission_allowed(BigBoxSecurityPermission::Exit)
            && !policy.permission_allowed(BigBoxSecurityPermission::ChangeFilterPlatforms)
            && *self.big_box_pin_configured()
            && !*self.big_box_locked()
            && *self.big_box_show_game_lock_unlock()
            && *self.big_box_security_settings_revision() == expected_revision
            && self.big_box_security_permission_count()
                == saturating_i32(BIG_BOX_SECURITY_PERMISSIONS.len())
            && self.rust().big_box_security_write_notifications == 1
            && counters_match
            && !*self.loading()
            && !*self.writing();
        if success {
            eprintln!(
                "BIGBOX_SECURITY_SMOKE_COMPLETE permissions={} blocked={blocked_actions} failures={failed_unlocks} unlocks={successful_unlocks} writes=1 pin=configured locked=0 revision={}",
                BIG_BOX_SECURITY_PERMISSIONS.len(),
                self.big_box_security_settings_revision()
            );
        } else {
            eprintln!(
                "BIGBOX_SECURITY_SMOKE_INCOMPLETE configured={} locked={} show_lock={} exit={} platforms={} permissions={} blocked={} failures={} unlocks={} writes={} initial_revision={initial_revision} revision={} loading={} writing={}",
                policy.pin_configured(),
                self.big_box_locked(),
                policy.show_game_lock_unlock,
                policy.permission_allowed(BigBoxSecurityPermission::Exit),
                policy.permission_allowed(BigBoxSecurityPermission::ChangeFilterPlatforms),
                self.big_box_security_permission_count(),
                self.rust().big_box_security_blocked_actions,
                self.rust().big_box_security_failed_unlocks,
                self.rust().big_box_security_successful_unlocks,
                self.rust().big_box_security_write_notifications,
                self.big_box_security_settings_revision(),
                self.loading(),
                self.writing()
            );
        }
        success
    }

    pub fn report_big_box_game_actions_smoke_success(
        &self,
        initial_revision: i32,
        game_id: QString,
        favorite: bool,
        star_rating: f64,
        favorite_first_seen: bool,
        popup_seen: bool,
        blocked_favorite_seen: bool,
    ) -> bool {
        let game_id = game_id.to_string();
        let game = self.rust().games.iter().find(|game| game.id == game_id);
        let policy = self.rust().big_box_game_action_policy;
        let security = &self.rust().big_box_security_policy;
        let expected_revision = initial_revision.wrapping_add(2);
        let game_matches = game.is_some_and(|game| {
            !game.favorite
                && !game.completed
                && game.star_rating == 2
                && (game.star_rating_float - 2.5).abs() <= 1.0e-9
        });
        let success = game_id == "fixture-adventure"
            && !favorite
            && (star_rating - 2.5).abs() <= 1.0e-9
            && favorite_first_seen
            && popup_seen
            && blocked_favorite_seen
            && policy.show_star_next_to_favorited_games
            && policy.show_favorited_games_first
            && policy.show_game_favorite
            && policy.show_game_menu_favorite
            && policy.show_game_menu_playlist_actions
            && policy.show_game_menu_star_rating
            && policy.show_game_star_rating
            && security.permission_allowed(BigBoxSecurityPermission::SetStarRating)
            && !security.permission_allowed(BigBoxSecurityPermission::FavoriteGames)
            && self.rust().big_box_security_blocked_actions == 1
            && self.rust().big_box_security_successful_unlocks == 1
            && self.rust().big_box_security_failed_unlocks == 0
            && self.rust().big_box_game_state_write_notifications == 2
            && *self.big_box_game_state_revision() == expected_revision
            && !*self.big_box_locked()
            && game_matches
            && !*self.loading()
            && !*self.writing()
            && !*self.write_conflict()
            && *self.pending_recovery_count() == 0;
        if success {
            eprintln!(
                "BIGBOX_GAME_ACTIONS_SMOKE_COMPLETE game=fixture-adventure favorite=0 rating=2.5 integer=2 completed=0 favorite_first=1 popup=1 blocked=1 unlocks=1 writes=2 revision={}",
                self.big_box_game_state_revision()
            );
        } else {
            eprintln!(
                "BIGBOX_GAME_ACTIONS_SMOKE_INCOMPLETE game={game_id} favorite={favorite} rating={star_rating} favorite_first={favorite_first_seen} popup={popup_seen} blocked={blocked_favorite_seen} policy={policy:?} security_rating={} security_favorite={} blocked_count={} unlocks={} failures={} writes={} initial_revision={initial_revision} revision={} locked={} game_matches={game_matches} loading={} writing={} conflict={} recovery={}",
                security.permission_allowed(BigBoxSecurityPermission::SetStarRating),
                security.permission_allowed(BigBoxSecurityPermission::FavoriteGames),
                self.rust().big_box_security_blocked_actions,
                self.rust().big_box_security_successful_unlocks,
                self.rust().big_box_security_failed_unlocks,
                self.rust().big_box_game_state_write_notifications,
                self.big_box_game_state_revision(),
                self.big_box_locked(),
                self.loading(),
                self.writing(),
                self.write_conflict(),
                self.pending_recovery_count()
            );
        }
        success
    }

    pub fn report_big_box_playlist_actions_smoke_success(
        &self,
        initial_revision: i32,
        game_id: QString,
        playlist_id: QString,
        popup_seen: bool,
        blocked_action_seen: bool,
        add_target_count: i32,
    ) -> bool {
        let game_id = game_id.to_string();
        let playlist_id = playlist_id.to_string();
        let rust = self.rust();
        let manual = rust
            .navigation_catalog
            .playlists
            .iter()
            .find(|document| document.playlist.id == playlist_id);
        let automatic = rust
            .navigation_catalog
            .playlists
            .iter()
            .find(|document| document.playlist.id == "fixture-playlist");
        let generated = rust
            .navigation_catalog
            .playlists
            .iter()
            .find(|document| document.playlist.id == "generated-playlist");
        let expected_revision = initial_revision.wrapping_add(2);
        let manual_matches = manual.is_some_and(|document| {
            is_manual_playlist_action_target(document)
                && document.games.len() == 1
                && document.games[0].game_id == "fixture-puzzle"
                && document.games[0].manual_order == 4
        });
        let automatic_matches = automatic.is_some_and(|document| {
            document.playlist.auto_populate
                && !document.playlist.is_autogenerated
                && document.games.len() == 1
                && document.games[0].game_id == "fixture-adventure"
        });
        let generated_matches = generated.is_some_and(|document| {
            !document.playlist.auto_populate
                && document.playlist.is_autogenerated
                && document.games.len() == 1
                && document.games[0].game_id == "fixture-racer"
        });
        let visible_game_id = rust
            .filtered_indices
            .first()
            .map(|index| rust.games[*index].id.as_str());
        let success = game_id == "fixture-adventure"
            && playlist_id == "manual-playlist"
            && popup_seen
            && blocked_action_seen
            && add_target_count == 1
            && rust
                .big_box_game_action_policy
                .show_game_menu_playlist_actions
            && rust.big_box_security_blocked_actions == 1
            && rust.big_box_security_successful_unlocks == 1
            && rust.big_box_security_failed_unlocks == 0
            && rust.big_box_playlist_membership_write_notifications == 2
            && *self.big_box_playlist_membership_revision() == expected_revision
            && rust.playlist_filter.as_deref() == Some("manual-playlist")
            && visible_game_id == Some("fixture-puzzle")
            && rust.filtered_indices.len() == 1
            && manual_matches
            && automatic_matches
            && generated_matches
            && !*self.big_box_locked()
            && !*self.loading()
            && !*self.writing()
            && !*self.write_conflict()
            && *self.pending_recovery_count() == 0;
        if success {
            eprintln!(
                "BIGBOX_PLAYLIST_ACTIONS_SMOKE_COMPLETE game=fixture-adventure playlist=manual-playlist targets=1 popup=1 blocked=1 unlocks=1 writes=2 revision={} final_visible=fixture-puzzle",
                self.big_box_playlist_membership_revision()
            );
        } else {
            eprintln!(
                "BIGBOX_PLAYLIST_ACTIONS_SMOKE_INCOMPLETE game={game_id} playlist={playlist_id} targets={add_target_count} popup={popup_seen} blocked={blocked_action_seen} policy={} blocked_count={} unlocks={} failures={} writes={} initial_revision={initial_revision} revision={} filter={:?} visible={visible_game_id:?} manual={manual_matches} automatic={automatic_matches} generated={generated_matches} locked={} loading={} writing={} conflict={} recovery={}",
                rust.big_box_game_action_policy
                    .show_game_menu_playlist_actions,
                rust.big_box_security_blocked_actions,
                rust.big_box_security_successful_unlocks,
                rust.big_box_security_failed_unlocks,
                rust.big_box_playlist_membership_write_notifications,
                self.big_box_playlist_membership_revision(),
                rust.playlist_filter,
                self.big_box_locked(),
                self.loading(),
                self.writing(),
                self.write_conflict(),
                self.pending_recovery_count()
            );
        }
        success
    }

    pub fn report_big_box_input_editor_smoke_success(&self) -> bool {
        let policy = self.rust().big_box_input_engine.policy();
        let edited_rule = (0..policy.controller_rule_count()).any(|index| {
            policy
                .controller_rule(index)
                .is_some_and(|(action, binding, hold)| {
                    action == BigBoxInputAction::Exit
                        && binding == ControllerBinding::Button(8)
                        && hold == Some(ControllerBinding::Button(7))
                })
        });
        let success = policy.gamepad_enabled
            && policy.use_all_controllers
            && policy.keyboard_wpf_key(BigBoxInputAction::Select, 1) == Some(69)
            && policy.keyboard_sequence(BigBoxInputAction::Select, 1) == Some("Z")
            && policy.controller_rule_count() == 18
            && policy.unsupported_controller_rule_count == 0
            && edited_rule
            && *self.big_box_gamepad_enabled()
            && *self.big_box_use_all_controllers()
            && *self.big_box_controller_rule_count() == 18
            && *self.big_box_unsupported_controller_rule_count() == 0
            && *self.big_box_input_revision() > 1
            && !*self.loading()
            && !*self.writing();
        if success {
            eprintln!(
                "BIGBOX_INPUT_EDITOR_SMOKE_COMPLETE actions=59 keyboard=Z controller_rules=18 hold=Button7 transaction=2 revision={}",
                self.big_box_input_revision()
            );
        } else {
            eprintln!(
                "BIGBOX_INPUT_EDITOR_SMOKE_INCOMPLETE keyboard={} wpf={} rules={} edited_rule={} enabled={} all_controllers={} unsupported={} revision={} loading={} writing={}",
                policy
                    .keyboard_sequence(BigBoxInputAction::Select, 1)
                    .unwrap_or("none"),
                policy
                    .keyboard_wpf_key(BigBoxInputAction::Select, 1)
                    .unwrap_or(-1),
                policy.controller_rule_count(),
                edited_rule,
                self.big_box_gamepad_enabled(),
                self.big_box_use_all_controllers(),
                self.big_box_unsupported_controller_rule_count(),
                self.big_box_input_revision(),
                self.loading(),
                self.writing()
            );
        }
        success
    }

    pub fn report_big_box_screensaver_smoke_success(
        &self,
        expected_enabled: bool,
        swap_count: i32,
        selection_count: i32,
        automatic_delay_elapsed_ms: i32,
        manual_start_seen: bool,
        input_stop_count: i32,
        explore_count: i32,
        presented_views_mask: i32,
        video_playback_seen: bool,
        video_ready: bool,
    ) -> bool {
        let candidates = &self.rust().big_box_screensaver_candidates;
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let candidate_matches = candidates.len() == 1
            && candidates.first().is_some_and(|candidate| {
                candidate.game_id == "fixture-adventure"
                    && candidate.title == "Fixture Adventure"
                    && candidate.platform == "Fixture Console"
                    && candidate.genre == "Adventure"
                    && candidate.release_date == "1999-03-04"
                    && candidate.play_time_seconds == 5400
                    && (candidate.star_rating - 4.25).abs() < f64::EPSILON
                    && [
                        candidate.media.background_path.as_deref(),
                        candidate.media.box_art_path.as_deref(),
                        candidate.media.screenshot_path.as_deref(),
                        candidate.media.video_path.as_deref(),
                    ]
                    .into_iter()
                    .all(|path| path.is_some_and(&safe_regular_file))
                    && candidate
                        .media
                        .background_path
                        .as_deref()
                        .and_then(Path::file_name)
                        .and_then(|name| name.to_str())
                        == Some("Fixture Adventure-01.svg")
                    && candidate
                        .media
                        .box_art_path
                        .as_deref()
                        .and_then(Path::file_name)
                        .and_then(|name| name.to_str())
                        == Some("Fixture Adventure-01.svg")
                    && candidate
                        .media
                        .screenshot_path
                        .as_deref()
                        .and_then(Path::file_name)
                        .and_then(|name| name.to_str())
                        == Some("Fixture Adventure-01.svg")
                    && candidate
                        .media
                        .video_path
                        .as_deref()
                        .and_then(Path::file_name)
                        .and_then(|name| name.to_str())
                        == Some("fixture-adventure.mp4")
            });
        let interaction_matches = if expected_enabled {
            swap_count >= 1
                && selection_count >= 3
                && (800..=5_000).contains(&automatic_delay_elapsed_ms)
                && input_stop_count >= 1
                && explore_count >= 1
        } else {
            selection_count >= 1
                && automatic_delay_elapsed_ms == 0
                && input_stop_count >= 1
                && explore_count == 0
        };
        let success = candidate_matches
            && *self.big_box_screensaver_enabled() == expected_enabled
            && *self.big_box_screensaver_delay_seconds() == 1
            && *self.big_box_screensaver_minimum_swap_time_ms() == 300
            && *self.big_box_screensaver_maximum_swap_time_ms() == 500
            && *self.big_box_screensaver_skip_games_missing_background()
            && *self.big_box_screensaver_skip_games_missing_box_art()
            && *self.big_box_screensaver_skip_games_missing_video()
            && self.big_box_screensaver_view().to_string() == "Screensaver3View"
            && *self.big_box_screensaver_video_volume_percent() == 40
            && *self.big_box_screensaver_master_volume_percent() == 50
            && *self.big_box_screensaver_candidate_count() == 1
            && self.big_box_screensaver_swap_time_ms(0) == 300
            && self.big_box_screensaver_swap_time_ms(200) == 500
            && manual_start_seen
            && presented_views_mask == 15
            && video_playback_seen
            && video_ready
            && interaction_matches
            && !*self.loading()
            && !*self.writing();
        if success {
            let enabled = u8::from(expected_enabled);
            eprintln!(
                "BIGBOX_SCREENSAVER_SMOKE_COMPLETE enabled={enabled} candidates=1 swaps={swap_count} selections={selection_count} auto_delay_ms={automatic_delay_elapsed_ms} manual=1 input_exit={input_stop_count} explore={explore_count} views=1-2-3-4 video=h264 volume=20 range=300-500"
            );
        }
        success
    }

    pub fn report_game_details_smoke_success(
        &self,
        row: i32,
        game_id: QString,
        image_url: QString,
    ) -> bool {
        let Some(game) = self.filtered_game(row) else {
            eprintln!(
                "GAME_DETAILS_SMOKE_REJECTED row={row} reason=missing-filtered-game argument_id={:?}",
                game_id.to_string()
            );
            return false;
        };
        let game_id = game_id.to_string();
        let Some(expected_image) = self.rust().front_image_paths.get(&game.id) else {
            eprintln!(
                "GAME_DETAILS_SMOKE_REJECTED row={row} reason=missing-front-image argument_id={game_id:?} model_id={:?}",
                game.id
            );
            return false;
        };
        let url = QUrl::from_user_input(&image_url, &QString::default());
        let Some(local_file) = url.to_local_file() else {
            eprintln!(
                "GAME_DETAILS_SMOKE_REJECTED row={row} reason=non-local-image argument_id={game_id:?} model_id={:?} image_url={:?}",
                game.id,
                image_url.to_string()
            );
            return false;
        };
        let local_file = PathBuf::from(local_file.to_string());
        let image_is_safe = fs::symlink_metadata(&local_file)
            .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink());
        let success = game.id == "fixture-adventure"
            && game_id == game.id
            && game.platform == "Fixture Console"
            && game.notes.as_deref()
                == Some("A synthetic adventure used to verify LaunchBox XML compatibility.")
            && game.developer.as_deref() == Some("Fixture Labs")
            && game.publisher.as_deref() == Some("Fixture Publishing")
            && game.play_count == 3
            && game.play_time_seconds == 5_400
            && game.last_played_date.as_deref() == Some("2026-07-22T10:00:00-07:00")
            && game.community_star_rating == 4.25
            && game.community_star_rating_total_votes == 42
            && game.installed == Some(true)
            && self
                .rust()
                .additional_applications_by_game
                .get(&game.id)
                .is_some_and(|applications| applications.len() == 1)
            && self
                .rust()
                .game_saves_by_game
                .get(&game.id)
                .is_some_and(|saves| saves.len() == 1)
            && local_file == *expected_image
            && image_is_safe;
        if success {
            eprintln!(
                "GAME_DETAILS_SMOKE_COMPLETE id={} play_count={} play_time={} community_rating={:.2} applications=1 saves=1",
                game.id,
                game.play_count,
                game.play_time_seconds,
                game.community_star_rating,
            );
        } else {
            eprintln!(
                "GAME_DETAILS_SMOKE_REJECTED row={row} argument_id={game_id:?} model_id={:?} platform={:?} play_count={} play_time={} last_played={:?} community_rating={} community_votes={} installed={:?} applications={} saves={} image={local_file:?} expected_image={expected_image:?} image_safe={image_is_safe}",
                game.id,
                game.platform,
                game.play_count,
                game.play_time_seconds,
                game.last_played_date,
                game.community_star_rating,
                game.community_star_rating_total_votes,
                game.installed,
                self.rust()
                    .additional_applications_by_game
                    .get(&game.id)
                    .map_or(0, Vec::len),
                self.rust()
                    .game_saves_by_game
                    .get(&game.id)
                    .map_or(0, Vec::len),
            );
        }
        success
    }

    pub fn report_game_details_media_smoke_success(
        &self,
        game_id: QString,
        image_index: i32,
        video_index: i32,
        image_url: QString,
        video_url: QString,
    ) -> bool {
        let game_id = game_id.to_string();
        let Some(items) = self.rust().game_media_by_game_id.get(&game_id) else {
            return false;
        };
        let Some(image) = usize::try_from(image_index)
            .ok()
            .and_then(|index| items.get(index))
        else {
            return false;
        };
        let Some(video) = usize::try_from(video_index)
            .ok()
            .and_then(|index| items.get(index))
        else {
            return false;
        };
        let image_url = QUrl::from_user_input(&image_url, &QString::default());
        let video_url = QUrl::from_user_input(&video_url, &QString::default());
        let Some(image_file) = image_url
            .to_local_file()
            .map(|path| PathBuf::from(path.to_string()))
        else {
            return false;
        };
        let Some(video_file) = video_url
            .to_local_file()
            .map(|path| PathBuf::from(path.to_string()))
        else {
            return false;
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let full_scan_is_indexed = self
            .rust()
            .full_image_paths
            .get(&game_id)
            .is_some_and(|path| {
                safe_regular_file(path)
                    && items.iter().any(|item| {
                        item.kind == GameMediaKind::Image
                            && item.media_type == "Box - Full"
                            && item.path.as_path() == path.as_path()
                    })
            });
        let success = game_id == "fixture-adventure"
            && items.len() == 10
            && *self.indexed_media_count() == 10
            && image.kind == GameMediaKind::Image
            && image.media_type == "Box - Front"
            && image.path == image_file
            && safe_regular_file(&image_file)
            && video.kind == GameMediaKind::Video
            && video.media_type == "Video Snap"
            && video.path == video_file
            && safe_regular_file(&video_file)
            && self.game_media_default_index(qstring(&game_id)) == video_index
            && *self.details_show_video()
            && *self.details_auto_play_video()
            && full_scan_is_indexed
            && !*self.loading()
            && !*self.writing();
        if success {
            eprintln!(
                "GAME_DETAILS_MEDIA_SMOKE_COMPLETE id={game_id} items=10 image=Box-Front full=Box-Full video=Video-Snap autoplay=1"
            );
        }
        success
    }

