    pub fn report_library_list_view_smoke_success(
        &self,
        reloaded: bool,
        selected_game_id: QString,
    ) -> bool {
        let selected_game_id = selected_game_id.to_string();
        let rust = self.rust();
        let ordered_ids = rust
            .filtered_indices
            .iter()
            .map(|index| rust.games[*index].id.as_str())
            .collect::<Vec<_>>();
        let expected_selected = if reloaded {
            "fixture-racer"
        } else {
            "fixture-adventure"
        };
        let list_layout = &rust.list_view_column_layout;
        let list_columns_match = list_layout.ordered_columns.len() == 35
            && list_layout
                .ordered_columns
                .first()
                .is_some_and(|name| name == "Badges")
            && list_layout
                .ordered_columns
                .get(1)
                .is_some_and(|name| name == "Play Count")
            && list_layout
                .ordered_columns
                .get(2)
                .is_some_and(|name| name == "Title")
            && list_layout.visible_column_indexes.len() == 34
            && !list_layout.visible_column_indexes.contains(&3)
            && rust.ui_state.list_view_column_widths.get("Title") == Some(&320);
        let success = rust.games.len() == 3
            && ordered_ids == ["fixture-racer", "fixture-adventure", "fixture-puzzle"]
            && *self.list_view()
            && self.game_sort().to_string() == GameSort::PlayCount.key()
            && *self.game_sort_descending()
            && selected_game_id == expected_selected
            && list_columns_match
            && *self.ui_state_ready()
            && !*self.writing()
            && !*self.write_conflict()
            && *self.pending_recovery_count() == 0;
        if success {
            eprintln!(
                "LIBRARY_LIST_VIEW_SMOKE_COMPLETE reload={} rows={} selected={} sort={} descending=true",
                i32::from(reloaded),
                ordered_ids.len(),
                selected_game_id,
                self.game_sort(),
            );
        }
        success
    }

    pub fn report_library_box_size_smoke_success(
        &self,
        reloaded: bool,
        selected_game_id: QString,
        cell_width: f64,
        cell_height: f64,
    ) -> bool {
        let selected_game_id = selected_game_id.to_string();
        let box_size = *self.box_size();
        let aspect_ratio = cell_width / cell_height;
        let rust = self.rust();
        let success = rust.games.len() == 3
            && !*self.list_view()
            && (box_size - 0.31).abs() < 0.000_01
            && selected_game_id == "fixture-adventure"
            && (350.0..=450.0).contains(&cell_width)
            && (500.0..=700.0).contains(&cell_height)
            && (aspect_ratio - 0.645).abs() < 0.002
            && !*self.writing()
            && !*self.write_conflict()
            && *self.pending_recovery_count() == 0;
        if success {
            eprintln!(
                "LIBRARY_BOX_SIZE_SMOKE_COMPLETE reload={} rows={} selected={} size={box_size:.2} cell={}x{}",
                i32::from(reloaded),
                rust.games.len(),
                selected_game_id,
                cell_width.round() as i64,
                cell_height.round() as i64,
            );
        }
        success
    }

