    pub fn report_game_grouping_smoke_success(&self, root_game_id: QString) -> bool {
        let root_game_id = root_game_id.to_string();
        let rust = self.rust();
        let root_exists = rust.games.iter().any(|game| game.id == root_game_id);
        let expanded_version_exists = rust.games.iter().any(|game| {
            game.id != root_game_id
                && game.platform == "Fixture Console"
                && game.application_path == r"Games\Fixture Racer\racer.rom"
        });
        let root_applications = rust
            .additional_applications_by_game
            .get(&root_game_id)
            .map(Vec::as_slice)
            .unwrap_or_default();
        let success = root_exists
            && expanded_version_exists
            && rust.games.len() == 3
            && root_applications.len() == 1
            && root_applications[0].id == "fixture-adventure-manual"
            && *self.game_grouping_revision() == 2
            && self.last_game_grouping_operation().to_string() == "expand"
            && self.last_game_grouping_root_id().to_string() == root_game_id
            && *self.last_game_grouping_removed_count() == 0
            && *self.last_game_grouping_created_count() == 1
            && !*self.loading()
            && !*self.writing()
            && !*self.write_conflict()
            && *self.pending_recovery_count() == 0;
        if success {
            eprintln!(
                "GAME_GROUPING_SMOKE_COMPLETE revisions={} games={} applications={}",
                self.game_grouping_revision(),
                rust.games.len(),
                root_applications.len()
            );
        }
        success
    }

    pub fn load_big_box_related_games(mut self: Pin<&mut Self>, game_id: QString) -> bool {
        if !*self.as_ref().big_box_show_game_menu_related_games() {
            self.as_mut()
                .set_status_message(qstring("Related Games is disabled in BigBox settings."));
            return false;
        }
        if *self.as_ref().big_box_locked()
            && !self
                .as_ref()
                .rust()
                .big_box_security_policy
                .allows_action_key("BigBoxShowDiscoveryCenter")
        {
            self.as_mut()
                .note_big_box_locked_action(qstring("BigBoxShowDiscoveryCenter"));
            return false;
        }
        let game_id = game_id.to_string();
        if !self
            .as_ref()
            .rust()
            .games
            .iter()
            .any(|game| game.id.eq_ignore_ascii_case(&game_id))
        {
            self.as_mut().set_status_message(qstring(format!(
                "Related Games seed is no longer available: {game_id}"
            )));
            return false;
        }

        let (generation, policy, games, alternate_names_by_game, launchbox_root) = {
            let mut rust = self.as_mut().rust_mut();
            rust.big_box_related_games_generation =
                rust.big_box_related_games_generation.wrapping_add(1);
            (
                rust.big_box_related_games_generation,
                rust.big_box_related_games_policy.clone(),
                rust.games.clone(),
                rust.alternate_names_by_game.clone(),
                rust.launchbox_root.clone(),
            )
        };
        self.as_mut().set_big_box_related_games_loading(true);
        self.as_mut()
            .set_big_box_related_games_json(QString::default());
        let revision = self
            .as_ref()
            .big_box_related_games_revision()
            .wrapping_add(1);
        self.as_mut().set_big_box_related_games_revision(revision);
        self.as_mut().set_status_message(qstring(format!(
            "Loading Related Games for {game_id} in the background..."
        )));

        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("bigbox-related-games".to_owned())
            .spawn(move || {
                let result = build_related_games_payload(
                    policy,
                    games,
                    alternate_names_by_game,
                    launchbox_root,
                    &game_id,
                )
                .and_then(|payload| {
                    let candidate_count = payload.candidate_count;
                    let metadata_loaded = payload.metadata_database_loaded;
                    let section_counts = payload
                        .sections
                        .iter()
                        .map(|section| {
                            format!("{}={}", section.key, section.items.len())
                        })
                        .collect::<Vec<_>>()
                        .join(",");
                    eprintln!(
                        "Related Games payload ready: game={} candidates={candidate_count} metadata={} {section_counts}",
                        payload.game_id,
                        usize::from(metadata_loaded)
                    );
                    serde_json::to_string(&payload)
                        .map(|json| (json, candidate_count, metadata_loaded))
                        .map_err(|error| format!("Could not encode Related Games: {error}"))
                });
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_big_box_related_games(
                            generation,
                            result,
                        );
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_status_message(qstring(format!(
                "Could not start Related Games loader: {error}"
            )));
            self.as_mut().set_big_box_related_games_loading(false);
            return false;
        }
        true
    }

    pub fn reveal_related_game(mut self: Pin<&mut Self>, game_id: QString) -> i32 {
        if *self.as_ref().big_box_locked()
            && !self
                .as_ref()
                .rust()
                .big_box_security_policy
                .allows_action_key("BigBoxShowDiscoveryCenter")
        {
            self.as_mut()
                .note_big_box_locked_action(qstring("BigBoxShowDiscoveryCenter"));
            return -1;
        }
        let game_id = game_id.to_string();
        let Some(game) = self
            .as_ref()
            .rust()
            .games
            .iter()
            .find(|game| game.id.eq_ignore_ascii_case(&game_id))
            .cloned()
        else {
            self.as_mut().set_status_message(qstring(format!(
                "Related game is no longer installed: {game_id}"
            )));
            return -1;
        };
        self.as_mut().set_search_text(QString::default());
        self.as_mut().set_platform_filter(QString::default());
        self.as_mut().set_game_state_filter(qstring("any"));
        self.as_mut().set_missing_media_filter(qstring("none"));
        self.as_mut().set_include_hidden_games(game.hidden);
        self.as_mut().set_include_broken_games(game.broken);
        self.as_mut().set_navigation_filter_kind(QString::default());
        self.as_mut().set_navigation_filter_key(QString::default());
        self.as_mut().rust_mut().category_filter = None;
        self.as_mut().rust_mut().playlist_filter = None;
        self.as_mut().refresh_filtered_games();
        let row = self.as_ref().row_for_game_id(qstring(&game.id));
        self.as_mut()
            .set_status_message(qstring(format!("Selected related game: {}.", game.title)));
        row
    }

    pub fn load_big_box_discovery_center(mut self: Pin<&mut Self>) -> bool {
        if *self.as_ref().big_box_locked()
            && !self
                .as_ref()
                .rust()
                .big_box_security_policy
                .allows_action_key("BigBoxShowDiscoveryCenter")
        {
            self.as_mut()
                .note_big_box_locked_action(qstring("BigBoxShowDiscoveryCenter"));
            return false;
        }
        if self.as_ref().rust().games.is_empty() {
            self.as_mut()
                .set_status_message(qstring("The library has no games to discover."));
            return false;
        }

        let (generation, request_generation, games, cached, entropy) = {
            let mut rust = self.as_mut().rust_mut();
            rust.big_box_discovery_generation = rust.big_box_discovery_generation.wrapping_add(1);
            rust.random_selection_counter = rust.random_selection_counter.wrapping_add(1);
            (
                rust.big_box_discovery_generation,
                rust.request_generation,
                rust.games.clone(),
                rust.discovery_provider_cache.clone(),
                rust.random_selection_counter,
            )
        };
        if let Some(cached) = cached {
            let (catalog, state) = match cached.as_ref() {
                Ok(catalog) => (Some(catalog), BigBoxDiscoveryProviderState::Ready),
                Err(_) => (None, BigBoxDiscoveryProviderState::Unavailable),
            };
            let payload = project_big_box_discovery_with_provider(
                &games,
                Utc::now(),
                catalog,
                state,
                entropy,
            );
            let displayable = payload
                .sections
                .iter()
                .filter(|section| section.displayable)
                .count();
            let provider_lists = payload.provider.rendered_lists;
            let json = match serde_json::to_string(&payload) {
                Ok(json) => json,
                Err(error) => {
                    self.as_mut().set_status_message(qstring(format!(
                        "Could not encode the Discovery Center: {error}"
                    )));
                    return false;
                }
            };
            self.as_mut().set_big_box_discovery_loading(false);
            self.as_mut().set_big_box_discovery_json(qstring(json));
            let revision = self.as_ref().big_box_discovery_revision().wrapping_add(1);
            self.as_mut().set_big_box_discovery_revision(revision);
            self.as_mut().set_status_message(qstring(format!(
                "Discovery Center ready with {displayable} list(s), including {provider_lists} provider list(s)."
            )));
            return true;
        }

        let local_payload = project_big_box_discovery_with_provider(
            &games,
            Utc::now(),
            None,
            BigBoxDiscoveryProviderState::Loading,
            entropy,
        );
        let local_json = match serde_json::to_string(&local_payload) {
            Ok(json) => json,
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not encode the Discovery Center: {error}"
                )));
                return false;
            }
        };
        self.as_mut().set_big_box_discovery_loading(true);
        self.as_mut()
            .set_big_box_discovery_json(qstring(local_json));
        let revision = self.as_ref().big_box_discovery_revision().wrapping_add(1);
        self.as_mut().set_big_box_discovery_revision(revision);
        self.as_mut().set_status_message(qstring(
            "Local Discovery lists are ready; loading provider lists in the background...",
        ));

        let qt_thread = self.as_ref().qt_thread();
        let spawn_result = std::thread::Builder::new()
            .name("bigbox-discovery-provider".to_owned())
            .spawn(move || {
                let provider_result = fetch_discovery_catalog(&LaunchBoxDiscoveryTransport)
                    .map_err(|error| error.to_string());
                let (catalog, state) = match provider_result.as_ref() {
                    Ok(catalog) => (Some(catalog), BigBoxDiscoveryProviderState::Ready),
                    Err(_) => (None, BigBoxDiscoveryProviderState::Unavailable),
                };
                let payload = project_big_box_discovery_with_provider(
                    &games,
                    Utc::now(),
                    catalog,
                    state,
                    entropy,
                );
                let rendered_lists = payload.provider.rendered_lists;
                let rejected_lists = payload.provider.rejected_lists;
                let json = serde_json::to_string(&payload)
                    .map_err(|error| format!("Could not encode the Discovery Center: {error}"));
                qt_thread
                    .queue(move |mut controller| {
                        controller.as_mut().finish_big_box_discovery(
                            generation,
                            request_generation,
                            provider_result,
                            json,
                            rendered_lists,
                            rejected_lists,
                        );
                    })
                    .ok();
            });
        if let Err(error) = spawn_result {
            self.as_mut().set_big_box_discovery_loading(false);
            self.as_mut().rust_mut().discovery_provider_cache =
                Some(Err(format!("Could not start provider loader: {error}")));
            self.as_mut().set_status_message(qstring(format!(
                "Local Discovery lists are ready, but the provider loader could not start: {error}"
            )));
        }
        true
    }

