    pub fn emulator_id_at(&self, index: i32) -> QString {
        match index {
            0 => QString::default(),
            1 => qstring(UNASSIGNED_EMULATOR_ID),
            _ => usize::try_from(index - 2)
                .ok()
                .and_then(|index| {
                    self.rust()
                        .emulator_configuration
                        .as_ref()?
                        .emulators
                        .get(index)
                })
                .map(|emulator| qstring(&emulator.id))
                .unwrap_or_default(),
        }
    }

