    fn persist_path_mappings(
        mut self: Pin<&mut Self>,
        mappings: HostPathMappings,
        success_message: String,
    ) -> bool {
        let Some(path) = self.as_ref().rust().path_mapping_settings_file.clone() else {
            self.as_mut().set_status_message(qstring(
                "Host path mapping settings have not been initialized.",
            ));
            return false;
        };
        let resolver = match mappings
            .resolver()
            .map_err(|error| error.to_string())
            .and_then(path_resolver_from_command_line)
        {
            Ok(resolver) => resolver,
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not apply host path mappings: {error}"
                )));
                return false;
            }
        };
        if let Err(error) = mappings.save_atomic(&path) {
            self.as_mut().set_status_message(qstring(format!(
                "Could not save host path mappings: {error}"
            )));
            return false;
        }
        let count = i32::try_from(mappings.len()).unwrap_or(i32::MAX);
        self.as_mut().rust_mut().path_mappings = mappings;
        self.as_mut().rust_mut().path_resolver = resolver;
        self.as_mut().rust_mut().emulator_bios_audit = None;
        self.as_mut().rust_mut().emulator_bios_emulator_id = None;
        self.as_mut().rust_mut().pcsx2_release_state = None;
        self.as_mut().rust_mut().pcsx2_remove_state = None;
        self.as_mut().rust_mut().bigpemu_release_state = None;
        self.as_mut().rust_mut().bigpemu_remove_state = None;
        self.as_mut().rust_mut().xemu_release_state = None;
        self.as_mut().rust_mut().xemu_remove_state = None;
        self.as_mut().set_path_mapping_count(count);
        self.as_mut()
            .set_emulator_bios_audit_json(QString::default());
        self.as_mut().set_emulator_release_json(QString::default());
        self.as_mut().set_emulator_managed_json(QString::default());
        let bios_revision = self.as_ref().emulator_bios_revision().saturating_add(1);
        self.as_mut().set_emulator_bios_revision(bios_revision);
        let install_revision = self.as_ref().emulator_install_revision().saturating_add(1);
        self.as_mut()
            .set_emulator_install_revision(install_revision);
        self.as_mut().set_status_message(qstring(success_message));
        true
    }

    fn advance_generation(mut self: Pin<&mut Self>) -> u64 {
        let mut rust = self.as_mut().rust_mut();
        rust.request_generation = rust.request_generation.wrapping_add(1);
        rust.request_generation
    }

    fn library_operation_active(&self) -> bool {
        *self.loading()
            || *self.import_scanning()
            || *self.emulator_discovery_scanning()
            || *self.emulator_bios_scanning()
            || *self.emulator_release_checking()
            || *self.emulator_managed_checking()
            || *self.emulator_installing()
            || *self.writing()
            || *self.launching()
            || *self.shutdown_screen_active()
    }

    fn begin_library_mutation(mut self: Pin<&mut Self>) -> bool {
        if self.as_ref().library_operation_active() {
            self.as_mut()
                .set_status_message(qstring("Wait for the current library operation to finish."));
            return false;
        }
        if *self.as_ref().pending_recovery_count() > 0 {
            self.as_mut().set_status_message(qstring(
                "Recover the interrupted transaction before editing this library.",
            ));
            return false;
        }
        if *self.as_ref().write_conflict() {
            self.as_mut().set_status_message(qstring(
                "Reload the library before retrying an edit after a write conflict.",
            ));
            return false;
        }
        true
    }

    fn begin_data_backup_operation(mut self: Pin<&mut Self>) -> Option<PathBuf> {
        if *self.as_ref().frontend_is_big_box() {
            self.as_mut().set_status_message(qstring(
                "Create and restore data backups from LaunchBox desktop mode.",
            ));
            return None;
        }
        if !self.as_mut().begin_library_mutation() {
            return None;
        }
        if *self.as_ref().launch_session_active()
            || *self.as_ref().startup_screen_active()
            || *self.as_ref().pause_screen_active()
        {
            self.as_mut().set_status_message(qstring(
                "Wait for the current game session to finish before changing data backups.",
            ));
            return None;
        }
        let Some(root) = self.as_ref().rust().launchbox_root.clone() else {
            self.as_mut().set_status_message(qstring(
                "Load a LaunchBox library before creating or restoring a data backup.",
            ));
            return None;
        };
        Some(root)
    }

