    fn finish_big_box_game_state_write(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<BigBoxGameStateWriteSuccess, GameWriteFailure>,
    ) {
        if self.as_ref().rust().request_generation != generation {
            self.as_mut().set_writing(false);
            return;
        }
        match result {
            Ok(written) => {
                let actual_index = {
                    let this = self.as_ref();
                    let rust = this.rust();
                    rust.games
                        .iter()
                        .zip(&rust.game_sources)
                        .position(|(game, source)| {
                            game.id == written.game.id && *source == written.source
                        })
                };
                if let Some(actual_index) = actual_index {
                    self.as_mut().rust_mut().games[actual_index] = written.game;
                    self.as_mut()
                        .rust_mut()
                        .big_box_game_state_write_notifications = self
                        .as_ref()
                        .rust()
                        .big_box_game_state_write_notifications
                        .saturating_add(1);
                    self.as_mut().refresh_big_box_screensaver_candidates();
                    self.as_mut().refresh_filtered_games();
                    let revision = self.as_ref().big_box_game_state_revision().wrapping_add(1);
                    self.as_mut().set_big_box_game_state_revision(revision);
                    self.as_mut().set_write_conflict(false);
                    self.as_mut().set_status_message(qstring(format!(
                        "Saved BigBox favorite and star rating. Exact backup: {}",
                        written.backup.display()
                    )));
                } else {
                    self.as_mut().set_status_message(qstring(
                        "The saved game is no longer present in the loaded model; reload required.",
                    ));
                }
            }
            Err(GameWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict: {message}. Reload before retrying."
                )));
            }
            Err(GameWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(GameWriteFailure::Other(message)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not save BigBox favorite/rating state: {message}"
                )));
            }
            Err(GameWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not save BigBox favorite/rating state: {} dependent records were reported unexpectedly.",
                    references.len()
                )));
            }
        }
        // Install the committed model state and revision before observers see
        // the write complete.
        self.as_mut().set_writing(false);
    }

    fn finish_big_box_playlist_membership_write(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<BigBoxPlaylistMembershipWriteSuccess, PlatformWriteFailure>,
    ) {
        if self.as_ref().rust().request_generation != generation {
            self.as_mut().set_writing(false);
            return;
        }
        match result {
            Ok(written) => {
                let playlist_id = written.playlist.playlist.id.clone();
                let playlist_name = written.playlist.playlist.metadata.name.clone();
                let position = self
                    .as_ref()
                    .rust()
                    .navigation_catalog
                    .playlists
                    .iter()
                    .position(|document| {
                        document.playlist.id.eq_ignore_ascii_case(&playlist_id)
                            && document.source_path == written.source
                    });
                if let Some(position) = position {
                    {
                        let mut rust = self.as_mut().rust_mut();
                        rust.navigation_catalog.playlists[position] = written.playlist;
                        rust.big_box_playlist_membership_write_notifications = rust
                            .big_box_playlist_membership_write_notifications
                            .saturating_add(1);
                    }
                    self.as_mut().update_library_counts();
                    if self.as_ref().rust().playlist_filter.is_some() {
                        self.as_mut().refresh_filtered_games();
                    }
                    let revision = self
                        .as_ref()
                        .big_box_playlist_membership_revision()
                        .wrapping_add(1);
                    self.as_mut()
                        .set_big_box_playlist_membership_revision(revision);
                    self.as_mut().set_write_conflict(false);
                    let detail = if written.present {
                        format!("Added the selected game to playlist {playlist_name}.")
                    } else {
                        format!("Removed the selected game from playlist {playlist_name}.")
                    };
                    self.as_mut().set_status_message(qstring(format!(
                        "{detail} Exact backup: {}",
                        written.backup.display()
                    )));
                } else {
                    self.as_mut().set_status_message(qstring(
                        "The saved playlist is no longer present in the loaded catalog; reload required.",
                    ));
                }
            }
            Err(PlatformWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict during BigBox playlist membership update: {message}. Reload before retrying."
                )));
            }
            Err(PlatformWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(PlatformWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not update BigBox playlist membership: {} dependent records were reported unexpectedly.",
                    references.len()
                )));
            }
            Err(PlatformWriteFailure::Other(message)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not update BigBox playlist membership: {message}"
                )));
            }
        }
        // Publish the committed catalog, filter projection, and revision
        // before observers see the write complete.
        self.as_mut().set_writing(false);
    }

    fn finish_game_write(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<GameWriteSuccess, GameWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }

        match result {
            Ok(written) => {
                let actual_index = {
                    let this = self.as_ref();
                    let rust = this.rust();
                    rust.games
                        .iter()
                        .zip(&rust.game_sources)
                        .position(|(game, source)| {
                            game.id == written.game.id && *source == written.source
                        })
                };
                let Some(actual_index) = actual_index else {
                    self.as_mut().set_status_message(qstring(
                        "The saved game is no longer present in the loaded model; reload required.",
                    ));
                    return;
                };
                let GameWriteSuccess {
                    game,
                    alternate_names,
                    custom_fields,
                    resolved_model_settings,
                    source: _,
                    backup,
                } = written;
                let filtered_row = self
                    .as_ref()
                    .rust()
                    .filtered_indices
                    .iter()
                    .position(|index| *index == actual_index);
                let metadata_changed =
                    GameMetadata::from(&self.as_ref().rust().games[actual_index])
                        != GameMetadata::from(&game);
                let query_result_may_change = {
                    let filter = self.as_ref().current_filter();
                    game_query_result_may_change(
                        &self.as_ref().rust().games[actual_index],
                        &game,
                        &filter,
                    )
                };
                let game_id = game.id.clone();
                {
                    let mut rust = self.as_mut().rust_mut();
                    rust.games[actual_index] = game;
                    if alternate_names.is_empty() {
                        rust.alternate_names_by_game.remove(&game_id);
                    } else {
                        rust.alternate_names_by_game
                            .insert(game_id.clone(), alternate_names);
                    }
                    if custom_fields.is_empty() {
                        rust.custom_fields_by_game.remove(&game_id);
                    } else {
                        rust.custom_fields_by_game
                            .insert(game_id.clone(), custom_fields);
                    }
                    rust.resolved_model_settings_by_game
                        .insert(game_id, resolved_model_settings);
                }
                self.as_mut().refresh_big_box_screensaver_candidates();
                let model_revision = self.as_ref().model_settings_revision().saturating_add(1);
                self.as_mut().set_model_settings_revision(model_revision);
                self.as_mut().set_write_conflict(false);
                self.as_mut().set_status_message(qstring(format!(
                    "Saved game. Exact backup: {}",
                    backup.display()
                )));

                if metadata_changed || query_result_may_change {
                    self.as_mut().refresh_filtered_games();
                } else if let Some(filtered_row) = filtered_row {
                    let row = saturating_i32(filtered_row);
                    let parent = QModelIndex::default();
                    let index = self.as_ref().model_index(row, 0, &parent);
                    let mut roles = QList::<i32>::default();
                    for role in EDITABLE_GAME_ROLES {
                        roles.append_clone(&role);
                    }
                    self.as_mut().rust_mut().data_change_notifications += 1;
                    self.as_mut().emit_data_changed(&index, &index, &roles);
                }
            }
            Err(GameWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict: {message}. Reload before retrying."
                )));
            }
            Err(GameWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(GameWriteFailure::Other(message)) => {
                self.as_mut()
                    .set_status_message(qstring(format!("Could not save game state: {message}")));
            }
            Err(GameWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not save game: {} dependent records were reported unexpectedly.",
                    references.len()
                )));
            }
        }
    }

    fn finish_additional_application_write(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<AdditionalApplicationWriteSuccess, GameWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(success) => {
                let AdditionalApplicationWriteSuccess {
                    operation,
                    application,
                    game,
                    source,
                    backup,
                } = success;
                let game_id = application.game_id.clone();
                let actual_index = self
                    .as_ref()
                    .rust()
                    .games
                    .iter()
                    .zip(&self.as_ref().rust().game_sources)
                    .position(|(game, candidate_source)| {
                        game.id == game_id && *candidate_source == source
                    });
                let Some(actual_index) = actual_index else {
                    self.as_mut().set_status_message(qstring(
                        "The edited additional application's game is no longer present in the loaded model; reload required.",
                    ));
                    return;
                };

                let mut refresh_games = false;
                match operation {
                    AdditionalApplicationWriteOperation::Create => {
                        self.as_mut()
                            .rust_mut()
                            .additional_applications_by_game
                            .entry(game_id.clone())
                            .or_default()
                            .push(application.clone());
                        self.as_mut()
                            .set_last_added_additional_application_id(qstring(&application.id));
                    }
                    AdditionalApplicationWriteOperation::Edit => {
                        let updated = {
                            let mut rust = self.as_mut().rust_mut();
                            rust.additional_applications_by_game
                                .get_mut(&game_id)
                                .and_then(|applications| {
                                    applications
                                        .iter_mut()
                                        .find(|candidate| candidate.id == application.id)
                                })
                                .map(|existing| *existing = application.clone())
                                .is_some()
                        };
                        if !updated {
                            self.as_mut().set_status_message(qstring(
                                "The edited additional application is no longer present in the loaded model; reload required.",
                            ));
                            return;
                        }
                    }
                    AdditionalApplicationWriteOperation::Delete => {
                        let deleted = {
                            let mut rust = self.as_mut().rust_mut();
                            rust.additional_applications_by_game
                                .get_mut(&game_id)
                                .map(|applications| {
                                    let previous_count = applications.len();
                                    applications.retain(|candidate| candidate.id != application.id);
                                    applications.len() != previous_count
                                })
                                .unwrap_or(false)
                        };
                        if !deleted {
                            self.as_mut().set_status_message(qstring(
                                "The deleted additional application is no longer present in the loaded model; reload required.",
                            ));
                            return;
                        }
                        if self
                            .as_ref()
                            .last_added_additional_application_id()
                            .to_string()
                            == application.id
                        {
                            self.as_mut()
                                .set_last_added_additional_application_id(QString::default());
                        }
                    }
                    AdditionalApplicationWriteOperation::MakeDefault => {
                        let Some(game) = game else {
                            self.as_mut().set_status_message(qstring(
                                "The additional-application writer returned no default game; reload required.",
                            ));
                            return;
                        };
                        if game.id != game_id
                            || !self
                                .as_ref()
                                .rust()
                                .additional_applications_by_game
                                .get(&game_id)
                                .is_some_and(|applications| {
                                    applications
                                        .iter()
                                        .any(|candidate| candidate.id == application.id)
                                })
                        {
                            self.as_mut().set_status_message(qstring(
                                "The defaulted additional application no longer matches the loaded model; reload required.",
                            ));
                            return;
                        }
                        self.as_mut().rust_mut().games[actual_index] = game;
                        self.as_mut()
                            .set_last_default_additional_application_id(qstring(&application.id));
                        refresh_games = true;
                    }
                }
                self.as_mut()
                    .rust_mut()
                    .additional_application_write_notifications = self
                    .as_ref()
                    .rust()
                    .additional_application_write_notifications
                    .saturating_add(1);

                if refresh_games {
                    self.as_mut().refresh_filtered_games();
                } else {
                    let remove_empty_group = self
                        .as_ref()
                        .rust()
                        .additional_applications_by_game
                        .get(&game_id)
                        .is_some_and(Vec::is_empty);
                    if remove_empty_group {
                        self.as_mut()
                            .rust_mut()
                            .additional_applications_by_game
                            .remove(&game_id);
                    } else if let Some(applications) = self
                        .as_mut()
                        .rust_mut()
                        .additional_applications_by_game
                        .get_mut(&game_id)
                    {
                        applications.sort_by(|left, right| {
                            left.priority
                                .cmp(&right.priority)
                                .then_with(|| left.id.cmp(&right.id))
                        });
                    }

                    let revision = self
                        .as_ref()
                        .additional_application_revision()
                        .saturating_add(1);
                    self.as_mut().set_additional_application_revision(revision);
                    if let Some(filtered_row) = self
                        .as_ref()
                        .rust()
                        .filtered_indices
                        .iter()
                        .position(|index| *index == actual_index)
                    {
                        let row = saturating_i32(filtered_row);
                        let parent = QModelIndex::default();
                        let index = self.as_ref().model_index(row, 0, &parent);
                        let mut roles = QList::<i32>::default();
                        roles.append(GAME_ADDITIONAL_APPLICATION_COUNT_ROLE);
                        self.as_mut().rust_mut().data_change_notifications = self
                            .as_ref()
                            .rust()
                            .data_change_notifications
                            .saturating_add(1);
                        self.as_mut().emit_data_changed(&index, &index, &roles);
                    }
                }
                self.as_mut().set_write_conflict(false);
                let status = match operation {
                    AdditionalApplicationWriteOperation::Create => format!(
                        "Added {}. Exact backup: {}",
                        application.name,
                        backup.display()
                    ),
                    AdditionalApplicationWriteOperation::Edit => format!(
                        "Saved {}. Exact backup: {}",
                        application.name,
                        backup.display()
                    ),
                    AdditionalApplicationWriteOperation::Delete => format!(
                        "Deleted {}. Exact backup: {}",
                        application.name,
                        backup.display()
                    ),
                    AdditionalApplicationWriteOperation::MakeDefault => format!(
                        "Made {} the default. Exact backup: {}",
                        application.name,
                        backup.display()
                    ),
                };
                self.as_mut().set_status_message(qstring(status));
            }
            Err(GameWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict while changing additional application: {message}. Reload before retrying."
                )));
            }
            Err(GameWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(GameWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not change additional application: {} unexpected dependent records were reported.",
                    references.len()
                )));
            }
            Err(GameWriteFailure::Other(message)) => self.as_mut().set_status_message(qstring(
                format!("Could not change additional application: {message}"),
            )),
        }
    }

    fn finish_game_save_write(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<GameSaveWriteSuccess, GameWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(success) => {
                let GameSaveWriteSuccess {
                    game_id,
                    saves,
                    source,
                    backup,
                    operation,
                } = success;
                let actual_index = self
                    .as_ref()
                    .rust()
                    .games
                    .iter()
                    .zip(&self.as_ref().rust().game_sources)
                    .position(|(game, candidate_source)| {
                        game.id == game_id && *candidate_source == source
                    });
                let Some(actual_index) = actual_index else {
                    self.as_mut().set_status_message(qstring(
                        "The edited game-save owner is no longer present in the loaded model; reload required.",
                    ));
                    return;
                };
                self.as_mut()
                    .rust_mut()
                    .game_saves_by_game
                    .insert(game_id, saves);
                self.as_mut().rust_mut().game_save_write_notifications = self
                    .as_ref()
                    .rust()
                    .game_save_write_notifications
                    .saturating_add(1);
                let revision = self.as_ref().game_save_revision().saturating_add(1);
                self.as_mut().set_game_save_revision(revision);
                if let Some(filtered_row) = self
                    .as_ref()
                    .rust()
                    .filtered_indices
                    .iter()
                    .position(|index| *index == actual_index)
                {
                    let row = saturating_i32(filtered_row);
                    let parent = QModelIndex::default();
                    let index = self.as_ref().model_index(row, 0, &parent);
                    let mut roles = QList::<i32>::default();
                    roles.append(GAME_SAVE_COUNT_ROLE);
                    self.as_mut().rust_mut().data_change_notifications = self
                        .as_ref()
                        .rust()
                        .data_change_notifications
                        .saturating_add(1);
                    self.as_mut().emit_data_changed(&index, &index, &roles);
                }
                self.as_mut().set_write_conflict(false);
                self.as_mut().set_status_message(qstring(format!(
                    "{operation}. Exact backup: {}",
                    backup.display()
                )));
            }
            Err(GameWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict while changing save metadata: {message}. Reload before retrying."
                )));
            }
            Err(GameWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(GameWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not change save metadata: {} unexpected dependent records were reported.",
                    references.len()
                )));
            }
            Err(GameWriteFailure::Other(message)) => self.as_mut().set_status_message(qstring(
                format!("Could not change save metadata: {message}"),
            )),
        }
    }

    fn finish_game_save_scan(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<GameSaveScanSuccess, GameWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(success) => {
                let GameSaveScanSuccess {
                    game_id,
                    saves,
                    source,
                    backup,
                    discovered_count,
                    added_count,
                } = success;
                let actual_index = self
                    .as_ref()
                    .rust()
                    .games
                    .iter()
                    .zip(&self.as_ref().rust().game_sources)
                    .position(|(game, candidate_source)| {
                        game.id == game_id && *candidate_source == source
                    });
                let Some(actual_index) = actual_index else {
                    self.as_mut().set_status_message(qstring(
                        "The scanned game is no longer present in the loaded model; reload required.",
                    ));
                    return;
                };
                if added_count > 0 {
                    self.as_mut()
                        .rust_mut()
                        .game_saves_by_game
                        .insert(game_id, saves);
                    self.as_mut().rust_mut().game_save_write_notifications = self
                        .as_ref()
                        .rust()
                        .game_save_write_notifications
                        .saturating_add(1);
                    let revision = self.as_ref().game_save_revision().saturating_add(1);
                    self.as_mut().set_game_save_revision(revision);
                    if let Some(filtered_row) = self
                        .as_ref()
                        .rust()
                        .filtered_indices
                        .iter()
                        .position(|index| *index == actual_index)
                    {
                        let row = saturating_i32(filtered_row);
                        let parent = QModelIndex::default();
                        let index = self.as_ref().model_index(row, 0, &parent);
                        let mut roles = QList::<i32>::default();
                        roles.append(GAME_SAVE_COUNT_ROLE);
                        self.as_mut().rust_mut().data_change_notifications = self
                            .as_ref()
                            .rust()
                            .data_change_notifications
                            .saturating_add(1);
                        self.as_mut().emit_data_changed(&index, &index, &roles);
                    }
                }
                self.as_mut().set_write_conflict(false);
                let status = match backup {
                    Some(backup) => format!(
                        "Emulator adapters found {discovered_count} active save set(s) and added {added_count}. Exact XML backup: {}",
                        backup.display()
                    ),
                    None => format!(
                        "Emulator adapters found {discovered_count} active save set(s); all were already recorded."
                    ),
                };
                self.as_mut().set_status_message(qstring(status));
            }
            Err(GameWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict while recording emulator saves: {message}. Reload before retrying."
                )));
            }
            Err(GameWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(GameWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not record emulator saves: {} unexpected dependent records were reported.",
                    references.len()
                )));
            }
            Err(GameWriteFailure::Other(message)) => self.as_mut().set_status_message(qstring(
                format!("Could not scan configured emulator saves: {message}"),
            )),
        }
    }

    fn finish_game_launch(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<GameLaunchSuccess, String>,
    ) {
        self.as_mut().set_launching(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(launched) => {
                self.as_mut().rust_mut().launch_notifications =
                    self.as_ref().rust().launch_notifications.saturating_add(1);
                if *self.as_ref().startup_screen_active() {
                    self.as_mut().set_startup_screen_primary_started(true);
                }
                self.as_mut().set_last_launch_succeeded(true);
                self.as_mut()
                    .set_last_launch_game_id(qstring(&launched.game_id));
                self.as_mut()
                    .set_last_launch_target_id(qstring(&launched.target_id));
                self.as_mut().set_status_message(qstring(format!(
                    "Launched {} with {} (PID {}) from {}.",
                    launched.game_title,
                    launched.kind,
                    launched.pid,
                    launched.executable.display()
                )));
            }
            Err(error) => {
                self.as_mut().set_startup_screen_active(false);
                self.as_mut().set_startup_screen_primary_started(false);
                self.as_mut().set_last_launch_succeeded(false);
                self.as_mut().set_last_launch_game_id(QString::default());
                self.as_mut().set_last_launch_target_id(QString::default());
                self.as_mut()
                    .set_status_message(qstring(format!("Could not launch game: {error}")));
            }
        }
    }

    fn finish_play_session_stats(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<PlaySessionStatsWriteSuccess, GameWriteFailure>,
    ) {
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(updated) => {
                self.as_mut().rust_mut().session_stats_writes =
                    self.as_ref().rust().session_stats_writes.saturating_add(1);
                let _backup = updated.backup;
                match updated.record {
                    PlaySessionStatsRecord::Game(game) => {
                        let Some(actual_index) = self
                            .as_ref()
                            .rust()
                            .games
                            .iter()
                            .position(|candidate| candidate.id == game.id)
                        else {
                            self.as_mut().rust_mut().session_stats_error = Some(format!(
                                "updated game {} disappeared from the loaded model",
                                game.id
                            ));
                            return;
                        };
                        let statistics_changed = {
                            let controller = self.as_ref();
                            let previous = &controller.rust().games[actual_index];
                            previous.play_count != game.play_count
                                || previous.play_time_seconds != game.play_time_seconds
                                || previous.last_played_date != game.last_played_date
                        };
                        let query_result_may_change = {
                            let filter = self.as_ref().current_filter();
                            game_query_result_may_change(
                                &self.as_ref().rust().games[actual_index],
                                &game,
                                &filter,
                            )
                        };
                        self.as_mut().rust_mut().games[actual_index] = *game;
                        self.as_mut().refresh_big_box_screensaver_candidates();
                        if query_result_may_change {
                            self.as_mut().refresh_filtered_games();
                        } else if statistics_changed {
                            let filtered_row = self
                                .as_ref()
                                .rust()
                                .filtered_indices
                                .iter()
                                .position(|index| *index == actual_index);
                            if let Some(row) = filtered_row {
                                let parent = QModelIndex::default();
                                let index =
                                    self.as_ref().model_index(saturating_i32(row), 0, &parent);
                                let mut roles = QList::<i32>::default();
                                roles.append(GAME_PLAY_COUNT_ROLE);
                                roles.append(GAME_PLAY_TIME_SECONDS_ROLE);
                                roles.append(GAME_LAST_PLAYED_DATE_ROLE);
                                self.as_mut().rust_mut().data_change_notifications = self
                                    .as_ref()
                                    .rust()
                                    .data_change_notifications
                                    .saturating_add(1);
                                self.as_mut().emit_data_changed(&index, &index, &roles);
                            }
                        }
                    }
                    PlaySessionStatsRecord::AdditionalApplication(application) => {
                        let game_id = application.game_id.clone();
                        let parent_loaded = self
                            .as_ref()
                            .rust()
                            .additional_applications_by_game
                            .contains_key(&game_id);
                        let application_index = self
                            .as_ref()
                            .rust()
                            .additional_applications_by_game
                            .get(&game_id)
                            .and_then(|applications| {
                                applications
                                    .iter()
                                    .position(|candidate| candidate.id == application.id)
                            });
                        let Some(application_index) = application_index else {
                            let message = if parent_loaded {
                                format!(
                                    "updated additional application {} disappeared from the loaded model",
                                    application.id
                                )
                            } else {
                                format!(
                                    "updated additional application {} has no loaded parent",
                                    application.id
                                )
                            };
                            self.as_mut().rust_mut().session_stats_error = Some(message);
                            return;
                        };
                        self.as_mut()
                            .rust_mut()
                            .additional_applications_by_game
                            .get_mut(&game_id)
                            .expect("additional-application parent checked above")
                            [application_index] = *application;
                    }
                }
            }
            Err(error) => {
                let message = describe_game_write_failure(&error);
                self.as_mut().rust_mut().session_stats_error = Some(message.clone());
                match error {
                    GameWriteFailure::Conflict(_) => self.as_mut().set_write_conflict(true),
                    GameWriteFailure::PendingRecovery { count, .. } => self
                        .as_mut()
                        .set_pending_recovery_count(saturating_i32(count)),
                    GameWriteFailure::Referenced(_) | GameWriteFailure::Other(_) => {}
                }
                self.as_mut().set_status_message(qstring(format!(
                    "The application started, but play statistics could not be saved: {message}"
                )));
            }
        }
    }

    fn finish_launch_session(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<LaunchSequenceReport, String>,
        primary_started: bool,
        shutdown_title: String,
        shutdown: LaunchShutdownPolicy,
        session_stats_errors: Vec<String>,
    ) {
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        self.as_mut().rust_mut().launch_control_sender = None;
        self.as_mut().set_launch_session_active(false);
        self.as_mut().set_pause_screen_available(false);
        self.as_mut().set_pause_screen_active(false);
        self.as_mut().set_pause_screen_process_suspended(false);
        self.as_mut().rust_mut().pending_shutdown_screen = None;
        if primary_started && *self.as_ref().startup_screen_active() {
            if shutdown.enabled {
                self.as_mut().rust_mut().pending_shutdown_screen = Some((shutdown_title, shutdown));
            }
            self.as_mut().set_shutdown_screen_active(false);
            self.as_mut()
                .set_shutdown_screen_game_title(QString::default());
            self.as_mut()
                .set_shutdown_screen_settings_source(QString::default());
        } else if primary_started && shutdown.enabled {
            self.as_mut()
                .present_shutdown_screen(shutdown_title, shutdown);
        } else {
            self.as_mut().set_startup_screen_active(false);
            self.as_mut().set_startup_screen_primary_started(false);
            self.as_mut().set_shutdown_screen_active(false);
            self.as_mut()
                .set_shutdown_screen_game_title(QString::default());
            self.as_mut()
                .set_shutdown_screen_settings_source(QString::default());
        }
        if !primary_started {
            self.as_mut().set_launching(false);
        }
        match result {
            Ok(report) => {
                if report.delegated_descendant_observed {
                    self.as_mut().rust_mut().delegated_session_completions = self
                        .as_ref()
                        .rust()
                        .delegated_session_completions
                        .saturating_add(1);
                }
                let target = match &report.primary_target {
                    LaunchTarget::MainGame => report.game_title.clone(),
                    LaunchTarget::AdditionalApplication {
                        application_name, ..
                    } => format!("{} ({application_name})", report.game_title),
                };
                let exit = if report.primary_exit_success {
                    "successfully"
                } else {
                    "with an unsuccessful status"
                };
                let mut message = format!(
                    "Session for {target} ended {exit} after {} second(s).",
                    report.primary_runtime.as_secs()
                );
                if report.delegated_descendant_observed {
                    message.push_str(
                        " The directly started launcher delegated to another supervised process.",
                    );
                }
                if report.automatic_before_started > 0
                    || report.automatic_after_started > 0
                    || report.before_wait_timeouts > 0
                {
                    message.push_str(&format!(
                        " Started {} before-app(s) and {} after-app(s); {} before-app wait(s) reached the 30-second ceiling.",
                        report.automatic_before_started,
                        report.automatic_after_started,
                        report.before_wait_timeouts,
                    ));
                }
                if !session_stats_errors.is_empty() {
                    message.push_str(&format!(
                        " Play statistics were not fully saved: {}.",
                        session_stats_errors.join("; ")
                    ));
                }
                self.as_mut().set_status_message(qstring(message));
            }
            Err(error) if primary_started => {
                self.as_mut().set_status_message(qstring(format!(
                    "The primary application started, but its launch lifecycle failed: {error}"
                )));
            }
            Err(error) => {
                self.as_mut().set_last_launch_succeeded(false);
                self.as_mut().set_last_launch_game_id(QString::default());
                self.as_mut().set_last_launch_target_id(QString::default());
                self.as_mut()
                    .set_status_message(qstring(format!("Could not launch game: {error}")));
            }
        }
    }

    fn finish_game_add(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<GameAddSuccess, GameWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(added) => {
                let actual_index = self.as_ref().rust().games.len();
                let insertion_row = self.as_ref().game_insertion_row(&added.game);
                if let Some(row) = insertion_row {
                    let row = saturating_i32(row);
                    let parent = QModelIndex::default();
                    self.as_mut().begin_insert_rows(&parent, row, row);
                }
                {
                    let mut rust = self.as_mut().rust_mut();
                    rust.games.push(added.game.clone());
                    rust.game_sources.push(added.source);
                    if let Some(row) = insertion_row {
                        rust.filtered_indices.insert(row, actual_index);
                        rust.row_insert_notifications += 1;
                    }
                }
                self.as_mut().refresh_big_box_screensaver_candidates();
                if insertion_row.is_some() {
                    self.as_mut().end_insert_rows();
                }
                self.as_mut().update_library_counts();
                self.as_mut().set_write_conflict(false);
                self.as_mut()
                    .set_last_added_game_id(qstring(&added.game.id));
                self.as_mut().set_status_message(qstring(format!(
                    "Added {}. Exact backup: {}",
                    added.game.title,
                    added.backup.display()
                )));
            }
            Err(GameWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict while adding game: {message}. Reload before retrying."
                )));
            }
            Err(GameWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(GameWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not add game: unexpected reference result ({})",
                    references.len()
                )));
            }
            Err(GameWriteFailure::Other(message)) => self
                .as_mut()
                .set_status_message(qstring(format!("Could not add game: {message}"))),
        }
    }

    fn finish_platform_create(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<PlatformCreateSuccess, PlatformWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(created) => {
                {
                    let mut rust = self.as_mut().rust_mut();
                    rust.platform_names.push(created.name.clone());
                    rust.platform_names.sort_by_key(|name| platform_key(name));
                    rust.platform_names
                        .dedup_by(|left, right| platform_key(left) == platform_key(right));
                    rust.platform_sources
                        .insert(platform_key(&created.name), created.source.clone());
                    rust.navigation_catalog
                        .platforms
                        .push(created.platform.clone());
                }
                self.as_mut().update_library_counts();
                let platform_count = self.as_ref().rust().platform_names.len();
                self.as_mut().set_library_name(qstring(format!(
                    "LaunchBox Library ({platform_count} platforms)"
                )));
                self.as_mut().set_write_conflict(false);
                self.as_mut().set_status_message(qstring(format!(
                    "Created {} with {} default media-folder records at {}. Exact catalog backup: {}. No media directories were created.",
                    created.name,
                    created.folder_count,
                    created.source.display(),
                    created.catalog_backup.display()
                )));
            }
            Err(PlatformWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Write conflict while creating platform: {message}. Reload before retrying."
                )));
            }
            Err(PlatformWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery: {message}"
                )));
            }
            Err(PlatformWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not create platform: unexpected reference result ({})",
                    references.len()
                )));
            }
            Err(PlatformWriteFailure::Other(message)) => self
                .as_mut()
                .set_status_message(qstring(format!("Could not create platform: {message}"))),
        }
    }

    fn finish_emulator_discovery(
        mut self: Pin<&mut Self>,
        generation: u64,
        candidates: Vec<DiscoveredEmulatorExecutable>,
    ) {
        self.as_mut().set_emulator_discovery_scanning(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        let count = candidates.len();
        self.as_mut().rust_mut().discovered_emulators = candidates;
        let revision = self
            .as_ref()
            .emulator_discovery_revision()
            .saturating_add(1);
        self.as_mut().set_emulator_discovery_revision(revision);
        let registered = (0..count)
            .filter(|index| {
                self.as_ref()
                    .discovered_emulator_registered_at(*index as i32)
            })
            .count();
        self.as_mut().set_status_message(qstring(format!(
            "Found {count} reviewed emulator executable(s); {registered} already registered. Candidates were not executed or modified."
        )));
    }

    fn finish_emulator_bios_audit(
        mut self: Pin<&mut Self>,
        generation: u64,
        emulator_id: String,
        emulator_title: String,
        result: Result<EmulatorBiosAudit, String>,
    ) {
        self.as_mut().set_emulator_bios_scanning(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(audit) => {
                let payload =
                    match emulator_bios_audit_payload(&emulator_id, &emulator_title, &audit) {
                        Ok(payload) => payload,
                        Err(error) => {
                            self.as_mut().set_status_message(qstring(format!(
                                "Could not serialize emulator BIOS audit: {error}"
                            )));
                            return;
                        }
                    };
                let ready = audit.ready();
                let adapter = audit.adapter();
                let valid = audit.valid_count();
                let mismatch = audit.mismatch_count();
                let unsafe_count = audit.unsafe_count();
                let unreadable = audit.unreadable_count();
                let missing = audit.missing_count();
                let search_root = audit.search_root().to_path_buf();
                let adapter_name = match adapter {
                    "pcsx2" => "PCSX2",
                    "retroarch" => "RetroArch",
                    "xemu" => "Xemu",
                    _ => "Emulator",
                };
                {
                    let mut rust = self.as_mut().rust_mut();
                    rust.emulator_bios_audit = Some(audit);
                    rust.emulator_bios_emulator_id = Some(emulator_id);
                    rust.emulator_bios_scan_notifications =
                        rust.emulator_bios_scan_notifications.saturating_add(1);
                }
                self.as_mut().set_emulator_bios_audit_json(qstring(payload));
                let revision = self.as_ref().emulator_bios_revision().saturating_add(1);
                self.as_mut().set_emulator_bios_revision(revision);
                self.as_mut().set_status_message(qstring(format!(
                    "{} BIOS audit {} at {}: {valid} valid, {mismatch} hash mismatch, {unsafe_count} unsafe, {unreadable} unreadable, {missing} missing. No files or configuration were changed.",
                    adapter_name,
                    if ready { "ready" } else { "needs required firmware" },
                    search_root.display()
                )));
            }
            Err(error) => {
                self.as_mut()
                    .set_status_message(qstring(format!("Could not audit emulator BIOS: {error}")));
            }
        }
    }

    fn finish_managed_pcsx2_review(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<(PathBuf, Pcsx2RemoveState), EmulatorWriteFailure>,
    ) {
        self.as_mut().set_emulator_managed_checking(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok((root, state)) => {
                let payload = match pcsx2_remove_payload(&root, &state) {
                    Ok(payload) => payload,
                    Err(error) => {
                        self.as_mut().set_status_message(qstring(format!(
                            "Could not serialize the managed PCSX2 review: {error}"
                        )));
                        return;
                    }
                };
                let can_remove = state.can_remove;
                let owned_file_count = state
                    .audit
                    .as_ref()
                    .map_or(0, |audit| audit.installed_files.len().saturating_add(1));
                let blocked_reason = state.blocked_reason.clone();
                self.as_mut().rust_mut().pcsx2_remove_state = Some(state);
                self.as_mut().set_emulator_managed_json(qstring(payload));
                let revision = self.as_ref().emulator_install_revision().saturating_add(1);
                self.as_mut().set_emulator_install_revision(revision);
                self.as_mut().set_status_message(qstring(if can_remove {
                    format!(
                        "Managed PCSX2 removal is ready: {owned_file_count} exact port-owned file(s) can be removed; user settings and directories will be retained."
                    )
                } else {
                    format!(
                        "Managed PCSX2 removal is unavailable: {}",
                        blocked_reason.unwrap_or_else(|| "no removable managed install".into())
                    )
                }));
            }
            Err(EmulatorWriteFailure::Referenced(references)) => {
                let summary = summarize_emulator_references(&references);
                self.as_mut()
                    .set_delete_blocker_count(saturating_i32(references.len()));
                self.as_mut().set_delete_blocker_summary(qstring(&summary));
                self.as_mut().set_status_message(qstring(format!(
                    "Managed PCSX2 removal review found {} dependent record(s): {summary}",
                    references.len()
                )));
            }
            Err(EmulatorWriteFailure::Conflict(message))
            | Err(EmulatorWriteFailure::Other(message)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not review managed PCSX2 removal: {message}"
                )));
            }
            Err(EmulatorWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery before managed PCSX2 review: {message}"
                )));
            }
        }
    }

    fn finish_managed_pcsx2_remove(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<Pcsx2RemoveSuccess, EmulatorWriteFailure>,
    ) {
        self.as_mut().set_writing(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(success) => {
                let removed_emulator_id = success
                    .removed_emulator
                    .as_ref()
                    .map(|emulator| emulator.id.clone());
                {
                    let mut rust = self.as_mut().rust_mut();
                    rust.emulator_configuration = Some(success.configuration);
                    rust.discovered_emulators.clear();
                    rust.emulator_bios_audit = None;
                    rust.emulator_bios_emulator_id = None;
                    rust.pcsx2_release_state = None;
                    rust.pcsx2_remove_state = None;
                    rust.bigpemu_release_state = None;
                    rust.bigpemu_remove_state = None;
                    rust.xemu_release_state = None;
                    rust.xemu_remove_state = None;
                    rust.retroarch_release_state = None;
                    rust.retroarch_remove_state = None;
                    rust.emulator_write_notifications =
                        rust.emulator_write_notifications.saturating_add(1);
                    rust.emulator_remove_notifications =
                        rust.emulator_remove_notifications.saturating_add(1);
                }
                if removed_emulator_id
                    .as_deref()
                    .is_some_and(|id| self.as_ref().last_added_emulator_id().to_string() == id)
                {
                    self.as_mut().set_last_added_emulator_id(QString::default());
                }
                self.as_mut()
                    .set_emulator_bios_audit_json(QString::default());
                self.as_mut().set_emulator_release_json(QString::default());
                self.as_mut().set_emulator_managed_json(QString::default());
                self.as_mut().set_delete_blocker_count(0);
                self.as_mut().set_delete_blocker_summary(QString::default());
                self.as_mut().set_write_conflict(false);
                self.as_mut().set_pending_recovery_count(0);
                let emulator_revision = self.as_ref().emulator_revision().saturating_add(1);
                self.as_mut().set_emulator_revision(emulator_revision);
                let discovery_revision = self
                    .as_ref()
                    .emulator_discovery_revision()
                    .saturating_add(1);
                self.as_mut()
                    .set_emulator_discovery_revision(discovery_revision);
                let bios_revision = self.as_ref().emulator_bios_revision().saturating_add(1);
                self.as_mut().set_emulator_bios_revision(bios_revision);
                let install_revision = self.as_ref().emulator_install_revision().saturating_add(1);
                self.as_mut()
                    .set_emulator_install_revision(install_revision);
                let xml_result = match success.emulator_backup.as_ref() {
                    Some(backup) => format!(
                        " Removed emulator definition and {} mapping(s) from {}; exact XML backup: {}.",
                        success.removed_mapping_count,
                        success.emulator_document.display(),
                        backup.display()
                    ),
                    None => " No matching emulator definition remained to remove.".into(),
                };
                self.as_mut().set_status_message(qstring(format!(
                    "Removed {} verified port-owned PCSX2 file(s) with {} exact recovery copy/copies. User settings, unrelated files, and directories were retained.{xml_result}",
                    success.removed_file_count,
                    success.recovery_files.len()
                )));
                eprintln!(
                    "PCSX2 managed removal committed: files={} mappings={} emulator={}",
                    success.removed_file_count,
                    success.removed_mapping_count,
                    removed_emulator_id.as_deref().unwrap_or("already absent")
                );
            }
            Err(EmulatorWriteFailure::Referenced(references)) => {
                let summary = summarize_emulator_references(&references);
                self.as_mut()
                    .set_delete_blocker_count(saturating_i32(references.len()));
                self.as_mut().set_delete_blocker_summary(qstring(&summary));
                self.as_mut().set_status_message(qstring(format!(
                    "Managed PCSX2 removal blocked by {} dependent record(s): {summary}",
                    references.len()
                )));
            }
            Err(EmulatorWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "Managed PCSX2 removal stopped on a write conflict: {message}. Reload before retrying."
                )));
            }
            Err(EmulatorWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted PCSX2 removal requires recovery: {message}"
                )));
            }
            Err(EmulatorWriteFailure::Other(message)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not remove managed PCSX2: {message}"
                )));
            }
        }
    }

    fn finish_pcsx2_release_check(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<Pcsx2ReleaseState, EmulatorLifecycleError>,
    ) {
        self.as_mut().set_emulator_release_checking(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(state) => {
                let payload = match pcsx2_release_payload(&state) {
                    Ok(payload) => payload,
                    Err(error) => {
                        self.as_mut().set_status_message(qstring(format!(
                            "Could not serialize the PCSX2 release review: {error}"
                        )));
                        return;
                    }
                };
                let action = state.action;
                let version = state.offer.version.clone();
                let prerelease = state.offer.prerelease;
                let blocked_reason = state.blocked_reason.clone();
                self.as_mut().rust_mut().pcsx2_release_state = Some(state);
                self.as_mut().set_emulator_release_json(qstring(payload));
                let revision = self.as_ref().emulator_install_revision().saturating_add(1);
                self.as_mut().set_emulator_install_revision(revision);
                let release_kind = if prerelease { "nightly" } else { "stable" };
                let message = match action {
                    Pcsx2InstallAction::Install => format!(
                        "Official PCSX2 {release_kind} {version} is ready for a reviewed portable install."
                    ),
                    Pcsx2InstallAction::Update => format!(
                        "Official PCSX2 {release_kind} {version} is ready to update the managed portable install."
                    ),
                    Pcsx2InstallAction::Repair => format!(
                        "Official PCSX2 {release_kind} {version} is ready to repair the managed portable install."
                    ),
                    Pcsx2InstallAction::Current => format!(
                        "The managed portable PCSX2 install is current at {version}."
                    ),
                    Pcsx2InstallAction::Blocked => format!(
                        "Managed PCSX2 installation is blocked: {}",
                        blocked_reason.unwrap_or_else(|| "unsafe existing install state".into())
                    ),
                };
                self.as_mut().set_status_message(qstring(message));
            }
            Err(error) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not check PCSX2 releases: {error}"
                )));
            }
        }
    }

    fn finish_emulator_install_progress(mut self: Pin<&mut Self>, generation: u64, progress: f64) {
        if self.as_ref().rust().request_generation == generation
            && *self.as_ref().emulator_installing()
        {
            self.as_mut()
                .set_emulator_install_progress(progress.clamp(0.0, 1.0));
        }
    }

    fn finish_pcsx2_install(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<Pcsx2InstallSuccess, EmulatorWriteFailure>,
    ) {
        self.as_mut().set_emulator_installing(false);
        self.as_mut().rust_mut().emulator_install_cancel = None;
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok(success) => {
                let Pcsx2InstallSuccess {
                    emulator_write,
                    manifest,
                    executable,
                    installed_file_count,
                    created_file_count,
                    replaced_file_count,
                    recovery_files,
                } = success;
                let operation = emulator_write.operation;
                let emulator_id = emulator_write.emulator.id.clone();
                let emulator_title = emulator_write.emulator.title.clone();
                let mapping_count = emulator_write.mapping_count;
                let source = emulator_write.source.clone();
                let backup = emulator_write.backup.clone();
                {
                    let mut rust = self.as_mut().rust_mut();
                    rust.emulator_configuration = Some(emulator_write.configuration);
                    rust.discovered_emulators.clear();
                    rust.emulator_bios_audit = None;
                    rust.emulator_bios_emulator_id = None;
                    rust.pcsx2_release_state = None;
                    rust.pcsx2_remove_state = None;
                    rust.bigpemu_release_state = None;
                    rust.bigpemu_remove_state = None;
                    rust.xemu_release_state = None;
                    rust.xemu_remove_state = None;
                    rust.retroarch_release_state = None;
                    rust.retroarch_remove_state = None;
                    rust.emulator_write_notifications =
                        rust.emulator_write_notifications.saturating_add(1);
                    rust.emulator_install_notifications =
                        rust.emulator_install_notifications.saturating_add(1);
                }
                self.as_mut().set_emulator_install_progress(1.0);
                self.as_mut().set_emulator_release_json(QString::default());
                self.as_mut().set_emulator_managed_json(QString::default());
                self.as_mut()
                    .set_emulator_bios_audit_json(QString::default());
                let emulator_revision = self.as_ref().emulator_revision().saturating_add(1);
                self.as_mut().set_emulator_revision(emulator_revision);
                let discovery_revision = self
                    .as_ref()
                    .emulator_discovery_revision()
                    .saturating_add(1);
                self.as_mut()
                    .set_emulator_discovery_revision(discovery_revision);
                let bios_revision = self.as_ref().emulator_bios_revision().saturating_add(1);
                self.as_mut().set_emulator_bios_revision(bios_revision);
                let install_revision = self.as_ref().emulator_install_revision().saturating_add(1);
                self.as_mut()
                    .set_emulator_install_revision(install_revision);
                if operation == EmulatorWriteOperation::Create {
                    self.as_mut()
                        .set_last_added_emulator_id(qstring(&emulator_id));
                }
                self.as_mut().set_write_conflict(false);
                self.as_mut().set_pending_recovery_count(0);
                self.as_mut().set_status_message(qstring(format!(
                    "Installed verified PCSX2 {} at {} and {} platform mapping(s) in one transaction: {} managed file(s), {} created, {} replaced. Emulators.xml: {}; exact XML backup: {}; binary recovery copies: {}. Recheck releases to refresh status.",
                    manifest.version,
                    executable.display(),
                    mapping_count,
                    installed_file_count,
                    created_file_count,
                    replaced_file_count,
                    source.display(),
                    backup.display(),
                    recovery_files.len()
                )));
                eprintln!(
                    "PCSX2 managed install committed: emulator={emulator_title} id={emulator_id} version={} sha256={} files={installed_file_count}",
                    manifest.version, manifest.asset_sha256
                );
            }
            Err(EmulatorWriteFailure::Conflict(message)) => {
                self.as_mut().set_write_conflict(true);
                self.as_mut().set_status_message(qstring(format!(
                    "PCSX2 install stopped on a write conflict: {message}. Reload before retrying."
                )));
            }
            Err(EmulatorWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted PCSX2 transaction requires recovery: {message}"
                )));
            }
            Err(EmulatorWriteFailure::Referenced(references)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "PCSX2 install stopped on an unexpected reference result ({} records).",
                    references.len()
                )));
            }
            Err(EmulatorWriteFailure::Other(message)) if message == "download was cancelled" => {
                self.as_mut().set_status_message(qstring(
                    "PCSX2 installation cancelled; no library changes were committed.",
                ));
            }
            Err(EmulatorWriteFailure::Other(message)) => {
                self.as_mut()
                    .set_status_message(qstring(format!("Could not install PCSX2: {message}")));
            }
        }
    }

    fn finish_managed_bigpemu_review(
        mut self: Pin<&mut Self>,
        generation: u64,
        result: Result<(PathBuf, BigPEmuRemoveState), EmulatorWriteFailure>,
    ) {
        self.as_mut().set_emulator_managed_checking(false);
        if self.as_ref().rust().request_generation != generation {
            return;
        }
        match result {
            Ok((root, state)) => {
                let payload = match bigpemu_remove_payload(&root, &state) {
                    Ok(payload) => payload,
                    Err(error) => {
                        self.as_mut().set_status_message(qstring(format!(
                            "Could not serialize the managed BigPEmu review: {error}"
                        )));
                        return;
                    }
                };
                let can_remove = state.can_remove;
                let owned_file_count = state
                    .audit
                    .as_ref()
                    .map_or(0, |audit| audit.installed_files.len().saturating_add(1));
                let blocked_reason = state.blocked_reason.clone();
                self.as_mut().rust_mut().bigpemu_remove_state = Some(state);
                self.as_mut().set_emulator_managed_json(qstring(payload));
                let revision = self.as_ref().emulator_install_revision().saturating_add(1);
                self.as_mut().set_emulator_install_revision(revision);
                self.as_mut().set_status_message(qstring(if can_remove {
                    format!(
                        "Managed BigPEmu removal is ready: {owned_file_count} exact port-owned file(s) can be removed; user settings and directories will be retained."
                    )
                } else {
                    format!(
                        "Managed BigPEmu removal is unavailable: {}",
                        blocked_reason.unwrap_or_else(|| "no removable managed install".into())
                    )
                }));
            }
            Err(EmulatorWriteFailure::Referenced(references)) => {
                let summary = summarize_emulator_references(&references);
                self.as_mut()
                    .set_delete_blocker_count(saturating_i32(references.len()));
                self.as_mut().set_delete_blocker_summary(qstring(&summary));
                self.as_mut().set_status_message(qstring(format!(
                    "Managed BigPEmu removal review found {} dependent record(s): {summary}",
                    references.len()
                )));
            }
            Err(EmulatorWriteFailure::Conflict(message))
            | Err(EmulatorWriteFailure::Other(message)) => {
                self.as_mut().set_status_message(qstring(format!(
                    "Could not review managed BigPEmu removal: {message}"
                )));
            }
            Err(EmulatorWriteFailure::PendingRecovery { count, message }) => {
                self.as_mut()
                    .set_pending_recovery_count(saturating_i32(count));
                self.as_mut().set_status_message(qstring(format!(
                    "Interrupted transaction requires recovery before managed BigPEmu review: {message}"
                )));
            }
        }
    }

