    fn background_music_collection(
        &self,
        context_kind: &str,
        context_name: &str,
    ) -> Option<(String, &[PathBuf])> {
        if self
            .rust()
            .big_box_background_music_policy
            .use_context_specific_music
        {
            let context_key = background_music_context_key(context_name);
            let kind = context_kind.trim().to_ascii_lowercase();
            let specific = match kind.as_str() {
                "platform" => self
                    .rust()
                    .background_music_paths_by_platform
                    .get(&context_key),
                "playlist" => self
                    .rust()
                    .background_music_paths_by_playlist
                    .get(&context_key),
                "category" | "platform category" => self
                    .rust()
                    .background_music_paths_by_category
                    .get(&context_key),
                _ => None,
            };
            if let Some(paths) = specific.filter(|paths| !paths.is_empty()) {
                return Some((format!("{kind}:{context_key}"), paths.as_slice()));
            }
        }
        (!self.rust().background_music_paths.is_empty()).then(|| {
            (
                "default".to_string(),
                self.rust().background_music_paths.as_slice(),
            )
        })
    }

    fn background_music_path(
        &self,
        context_kind: &str,
        context_name: &str,
        track_index: i32,
    ) -> Option<&PathBuf> {
        let track_index = usize::try_from(track_index).ok()?;
        self.background_music_collection(context_kind, context_name)
            .and_then(|(_, tracks)| tracks.get(track_index))
    }

