    fn validate_image_viewer_smoke(
        &self,
        game_id: &str,
        first_media_index: i32,
        next_media_index: i32,
        first_image_url: QString,
        next_image_url: QString,
    ) -> bool {
        let Some(items) = self.rust().game_media_by_game_id.get(game_id) else {
            return false;
        };
        let Some(first_image) = usize::try_from(first_media_index)
            .ok()
            .and_then(|index| items.get(index))
        else {
            return false;
        };
        let Some(next_image) = usize::try_from(next_media_index)
            .ok()
            .and_then(|index| items.get(index))
        else {
            return false;
        };
        let local_file = |value: QString| {
            QUrl::from_user_input(&value, &QString::default())
                .to_local_file()
                .map(|path| PathBuf::from(path.to_string()))
        };
        let Some(first_file) = local_file(first_image_url) else {
            return false;
        };
        let Some(next_file) = local_file(next_image_url) else {
            return false;
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        game_id == "fixture-adventure"
            && items.len() == 10
            && self.game_image_count_for_game(qstring(game_id)) == 8
            && self.game_image_media_index_at(qstring(game_id), 0) == first_media_index
            && self.game_image_media_index_at(qstring(game_id), 1) == next_media_index
            && self.game_image_media_index_at(qstring(game_id), 2) == 2
            && self.game_image_media_index_at(qstring(game_id), 3) == 3
            && self.game_image_media_index_at(qstring(game_id), 4) == 4
            && self.game_image_media_index_at(qstring(game_id), 5) == 5
            && self.game_image_media_index_at(qstring(game_id), 6) == 6
            && self.game_image_media_index_at(qstring(game_id), 7) == 7
            && first_image.kind == GameMediaKind::Image
            && first_image.media_type == "Box - Front"
            && first_image.path == first_file
            && safe_regular_file(&first_file)
            && next_image.kind == GameMediaKind::Image
            && next_image.media_type == "Screenshot - Gameplay"
            && next_image.path == next_file
            && safe_regular_file(&next_file)
            && items[3].kind == GameMediaKind::Image
            && items[3].media_type == "Arcade - Marquee"
            && items[4].kind == GameMediaKind::Image
            && items[4].media_type == "Box - Back"
            && items[5].kind == GameMediaKind::Image
            && items[5].media_type == "Box - Full"
            && items[6].kind == GameMediaKind::Image
            && items[6].media_type == "Box - Spine"
            && items[7].kind == GameMediaKind::Image
            && items[7].media_type == "Clear Logo"
            && !*self.loading()
            && !*self.writing()
    }

    fn validate_box_flip_smoke(
        &self,
        game_id: &str,
        front_image_url: QString,
        back_image_url: QString,
    ) -> bool {
        let Some(front_path) = self.rust().front_image_paths.get(game_id) else {
            return false;
        };
        let Some(back_path) = self.rust().back_image_paths.get(game_id) else {
            return false;
        };
        let Some(front_file) = QUrl::from_user_input(&front_image_url, &QString::default())
            .to_local_file()
            .map(|path| PathBuf::from(path.to_string()))
        else {
            return false;
        };
        let Some(back_file) = QUrl::from_user_input(&back_image_url, &QString::default())
            .to_local_file()
            .map(|path| PathBuf::from(path.to_string()))
        else {
            return false;
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let Some(items) = self.rust().game_media_by_game_id.get(game_id) else {
            return false;
        };
        let has_media = |media_type: &str, path: &Path| {
            items.iter().any(|item| {
                item.kind == GameMediaKind::Image
                    && item.media_type == media_type
                    && item.path == path
            })
        };
        game_id == "fixture-adventure"
            && items.len() == 10
            && self.game_image_count_for_game(qstring(game_id)) == 8
            && self.rust().front_image_paths.len() == 1
            && self.rust().back_image_paths.len() == 1
            && front_path == &front_file
            && back_path == &back_file
            && front_path != back_path
            && safe_regular_file(&front_file)
            && safe_regular_file(&back_file)
            && has_media("Box - Front", &front_file)
            && has_media("Box - Back", &back_file)
            && !*self.loading()
            && !*self.writing()
    }

    fn validate_box_model_viewer_smoke(
        &self,
        game_id: &str,
        front_image_url: QString,
        back_image_url: QString,
        spine_image_url: QString,
        full_image_url: QString,
        expected_lock: ModelRotationLock,
    ) -> bool {
        let Some(front_path) = self.rust().front_image_paths.get(game_id) else {
            return false;
        };
        let Some(back_path) = self.rust().back_image_paths.get(game_id) else {
            return false;
        };
        let Some(spine_path) = self.rust().spine_image_paths.get(game_id) else {
            return false;
        };
        let Some(full_path) = self.rust().full_image_paths.get(game_id) else {
            return false;
        };
        let local_file = |value: QString| {
            QUrl::from_user_input(&value, &QString::default())
                .to_local_file()
                .map(|path| PathBuf::from(path.to_string()))
        };
        let Some(front_file) = local_file(front_image_url) else {
            return false;
        };
        let Some(back_file) = local_file(back_image_url) else {
            return false;
        };
        let Some(spine_file) = local_file(spine_image_url) else {
            return false;
        };
        let Some(full_file) = local_file(full_image_url) else {
            return false;
        };
        let safe_regular_file = |path: &Path| {
            fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        };
        let Some(items) = self.rust().game_media_by_game_id.get(game_id) else {
            return false;
        };
        let has_media = |media_type: &str, path: &Path| {
            items.iter().any(|item| {
                item.kind == GameMediaKind::Image
                    && item.media_type == media_type
                    && item.path == path
            })
        };
        let persisted_lock = self
            .rust()
            .model_viewer_state_file
            .as_deref()
            .and_then(|path| ModelViewerState::load(path).ok())
            .map(|state| state.rotation_lock);
        let Some(game_model) = self.rust().resolved_model_settings_by_game.get(game_id) else {
            return false;
        };
        let Some(platform_model) = self
            .rust()
            .resolved_model_settings_by_game
            .get("fixture-racer")
        else {
            return false;
        };
        game_id == "fixture-adventure"
            && items.len() == 10
            && self.game_image_count_for_game(qstring(game_id)) == 8
            && self.rust().front_image_paths.len() == 1
            && self.rust().back_image_paths.len() == 1
            && self.rust().spine_image_paths.len() == 1
            && self.rust().full_image_paths.len() == 1
            && front_path == &front_file
            && back_path == &back_file
            && spine_path == &spine_file
            && full_path == &full_file
            && front_path != back_path
            && front_path != spine_path
            && back_path != spine_path
            && safe_regular_file(&front_file)
            && safe_regular_file(&back_file)
            && safe_regular_file(&spine_file)
            && safe_regular_file(&full_file)
            && has_media("Box - Front", &front_file)
            && has_media("Box - Back", &back_file)
            && has_media("Box - Spine", &spine_file)
            && has_media("Box - Full", &full_file)
            && game_model.source == ModelSettingsSource::GameOverride
            && game_model.settings.effective_model_type() == &ModelType::JewelCase
            && game_model
                .settings
                .case_color
                .is_some_and(|color| color.raw() == -15_654_349)
            && game_model
                .settings
                .cover_color
                .is_some_and(|color| color.raw() == -12_298_906)
            && game_model.settings.front_spine_image.as_deref()
                == Some(r"{Resources}\Fixture Jewel Spine")
            && game_model.settings.front_spine_is_clear
            && (game_model.settings.full_image_spine_width - 0.143).abs() < f64::EPSILON
            && game_model.settings.use_full_scan_images
            && platform_model.source == ModelSettingsSource::PlatformOverride
            && platform_model.settings.effective_model_type() == &ModelType::DvdCase
            && self.rust().model_viewer_state.rotation_lock == expected_lock
            && persisted_lock == Some(expected_lock)
            && self.model_rotation_lock().to_string() == expected_lock.key()
            && *self.model_viewer_state_ready()
            && *self.details_show_3d_model()
            && *self.big_box_show_game_menu_model()
            && !*self.loading()
            && !*self.writing()
    }

