        let revision = FileRevision {
            byte_len: 1,
            sha256: "00".into(),
        };
        let conflict = classify_transaction_error(TransactionError::Conflict {
            path: PathBuf::from("platform.xml"),
            expected: revision.clone(),
            actual: revision,
        });
        assert!(matches!(conflict, GameWriteFailure::Conflict(_)));
