    #[test]
    fn state_edits_and_first_play_recompute_active_filter_membership() {
        let mut previous = Game {
            id: "fixture".into(),
            title: "Fixture".into(),
            platform: "Console".into(),
            favorite: true,
            ..Game::default()
        };
        let mut next = previous.clone();
        next.favorite = false;
        assert!(game_query_result_may_change(
            &previous,
            &next,
            &GameFilter {
                state: GameStateFilter::Favorite,
                ..GameFilter::default()
            }
        ));
        assert!(!game_query_result_may_change(
            &previous,
            &next,
            &GameFilter::default()
        ));

        previous.favorite = false;
        next = previous.clone();
        next.play_count = 1;
        next.last_played_date = Some("2026-07-23T12:00:00-07:00".into());
        assert!(game_query_result_may_change(
            &previous,
            &next,
            &GameFilter {
                state: GameStateFilter::NeverPlayed,
                ..GameFilter::default()
            }
        ));
        assert!(game_query_result_may_change(
            &previous,
            &next,
            &GameFilter {
                state: GameStateFilter::Played,
                ..GameFilter::default()
            }
        ));
    }

    #[test]
    fn dolphin_directory_signatures_accept_legacy_md5_but_reject_malformed_or_changed_sha256() {
        let revision = DirectoryRevision {
            file_count: 1,
            directory_count: 0,
            byte_len: 4,
            sha256: "ab".repeat(32),
        };
        let mut save = GameSave::default();
        assert!(persisted_dolphin_directory_signature_matches(
            &save, &revision
        ));

        save.md5 = Some("12".repeat(16));
        assert!(persisted_dolphin_directory_signature_matches(
            &save, &revision
        ));

        save.md5 = Some(revision.sha256.to_ascii_uppercase());
        assert!(persisted_dolphin_directory_signature_matches(
            &save, &revision
        ));

        save.md5 = Some("cd".repeat(32));
        assert!(!persisted_dolphin_directory_signature_matches(
            &save, &revision
        ));
        save.md5 = Some("not-a-signature".into());
        assert!(!persisted_dolphin_directory_signature_matches(
            &save, &revision
        ));
    }

