    fn xemu_zip_test_offer(
        fixture: &Path,
        source: &Path,
        version: &str,
        artifact_kind: XemuArtifactKind,
        members: &[&str],
    ) -> XemuReleaseOffer {
        let asset_name = artifact_kind.expected_asset_name(version);
        let asset = fixture.join(&asset_name);
        let mut command = Command::new("7z");
        command
            .current_dir(source)
            .arg("a")
            .arg("-tzip")
            .arg("-bd")
            .arg("-bb0")
            .arg("-y")
            .arg(&asset)
            .arg("--");
        for member in members {
            command.arg(member);
        }
        let output = command.output().expect("create Xemu ZIP fixture");
        assert!(
            output.status.success(),
            "could not create Xemu ZIP fixture: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        let receipt = file_receipt(&asset).expect("hash Xemu ZIP fixture");
        XemuReleaseOffer {
            version: version.into(),
            tag: format!("v{version}"),
            release_name: format!("Xemu v{version}"),
            release_url: format!("https://github.com/xemu-project/xemu/releases/tag/v{version}"),
            prerelease: false,
            artifact_kind,
            asset_name: asset_name.clone(),
            asset_url: format!(
                "https://github.com/xemu-project/xemu/releases/download/v{version}/{asset_name}"
            ),
            asset_byte_len: receipt.byte_len,
            asset_sha256: receipt.sha256,
        }
    }

    #[cfg(unix)]
    fn retroarch_linux_test_offer(
        fixture: &Path,
        version: &str,
        frontend_bytes: &[u8],
        core_bytes: &[u8],
    ) -> RetroArchReleaseOffer {
        let wrapper = "RetroArch-Linux-x86_64";
        let source_key = version.replace('.', "-");
        let frontend_source = fixture.join(format!("retroarch-frontend-{source_key}"));
        let cores_source = fixture.join(format!("retroarch-cores-{source_key}"));
        let executable = frontend_source
            .join(wrapper)
            .join("RetroArch-Linux-x86_64.AppImage");
        let assets = frontend_source
            .join(wrapper)
            .join("RetroArch-Linux-x86_64.AppImage.home/.config/retroarch/assets/menu.txt");
        let core = cores_source.join(wrapper).join(
            "RetroArch-Linux-x86_64.AppImage.home/.config/retroarch/cores/fixture_libretro.so",
        );
        fs::create_dir_all(executable.parent().unwrap()).unwrap();
        fs::create_dir_all(assets.parent().unwrap()).unwrap();
        fs::create_dir_all(core.parent().unwrap()).unwrap();
        fs::write(&executable, frontend_bytes).unwrap();
        fs::write(&assets, format!("assets for {version}\n")).unwrap();
        fs::write(&core, core_bytes).unwrap();

        let frontend_archive = fixture.join("RetroArch.7z");
        let cores_archive = fixture.join("RetroArch_cores.7z");
        if frontend_archive.exists() {
            fs::remove_file(&frontend_archive).unwrap();
        }
        if cores_archive.exists() {
            fs::remove_file(&cores_archive).unwrap();
        }
        for (source, archive) in [
            (&frontend_source, &frontend_archive),
            (&cores_source, &cores_archive),
        ] {
            let output = Command::new("7z")
                .current_dir(source)
                .arg("a")
                .arg("-t7z")
                .arg("-bd")
                .arg("-bb0")
                .arg("-y")
                .arg(archive)
                .arg("--")
                .arg(wrapper)
                .output()
                .expect("create RetroArch 7z fixture");
            assert!(
                output.status.success(),
                "could not create RetroArch fixture: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        }
        fs::write(
            fixture.join("stable.html"),
            format!(r#"<a href="{version}/">{version}</a>"#),
        )
        .unwrap();
        fetch_latest_retroarch_release(
            &FileRetroArchReleaseTransport::new(fixture),
            RetroArchArtifactKind::Linux7zX64,
        )
        .expect("fetch RetroArch fixture release")
    }

    #[cfg(unix)]
    #[test]
    fn managed_retroarch_install_update_repair_review_and_removal_are_exact() {
        use std::os::unix::fs::PermissionsExt;

        let directory = tempfile::tempdir().expect("temporary library");
        let fixture = tempfile::tempdir().expect("release fixture");
        let data = directory.path().join("Data");
        fs::create_dir(&data).expect("create Data");
        let platform_directory = data.join("Platforms");
        fs::create_dir(&platform_directory).expect("create Platforms");
        fs::copy(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../fixtures/launchbox/Data/Platforms/Fixture Console.xml"),
            platform_directory.join("Fixture Console.xml"),
        )
        .expect("copy platform fixture");
        let emulator_document = data.join("Emulators.xml");
        fs::copy(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../fixtures/launchbox/Data/Emulators.xml"),
            &emulator_document,
        )
        .unwrap();
        let original_xml = fs::read(&emulator_document).unwrap();
        let resolver = HostPathResolver::default();
        let first_offer = retroarch_linux_test_offer(
            fixture.path(),
            "1.22.2",
            b"first RetroArch AppImage\n",
            b"first fixture core\n",
        );
        let initial_configuration = AuxiliaryDocument::load(&emulator_document)
            .unwrap()
            .emulator_configuration()
            .unwrap();
        let first_state = inspect_retroarch_release_state(
            directory.path(),
            Some(&initial_configuration),
            &resolver,
            first_offer,
        )
        .expect("inspect initial RetroArch install");
        assert_eq!(first_state.action, RetroArchInstallAction::Install);
        let first = install_managed_retroarch(
            directory.path().to_path_buf(),
            resolver.clone(),
            Vec::new(),
            first_state,
            Box::new(FileRetroArchReleaseTransport::new(fixture.path())),
            Arc::new(AtomicBool::new(false)),
            |_, _| {},
        )
        .expect("install managed RetroArch");
        assert_eq!(first.manifest.profile_id, "retroarch");
        assert_eq!(first.manifest.provider, RETROARCH_PROVIDER);
        assert_eq!(first.manifest.schema_version, 3);
        assert_eq!(first.manifest.supporting_artifacts.len(), 1);
        assert_eq!(first.manifest.supporting_artifacts[0].role, "cores");
        assert!(first.manifest.installed_links.is_empty());
        assert_eq!(
            fs::read(&first.emulator_write.backup).unwrap(),
            original_xml
        );
        assert_eq!(
            fs::read(&first.executable).unwrap(),
            b"first RetroArch AppImage\n"
        );
        assert_ne!(
            fs::metadata(&first.executable)
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );
        assert_eq!(
            first.emulator_write.emulator.application_path,
            r"Emulators\RetroArch\RetroArch-Linux-x86_64.AppImage"
        );

        let install_directory = directory.path().join("Emulators/RetroArch");
        let user_configuration = install_directory.join("retroarch.cfg");
        let user_save = install_directory.join("saves/user.srm");
        fs::create_dir_all(user_save.parent().unwrap()).unwrap();
        fs::write(&user_configuration, b"user configuration\n").unwrap();
        fs::write(&user_save, b"user save\n").unwrap();
        let before_update_xml = fs::read(&emulator_document).unwrap();
        let configuration = AuxiliaryDocument::load(&emulator_document)
            .unwrap()
            .emulator_configuration()
            .unwrap();
        let second_offer = retroarch_linux_test_offer(
            fixture.path(),
            "1.22.3",
            b"second RetroArch AppImage\n",
            b"second fixture core\n",
        );
        let second_state = inspect_retroarch_release_state(
            directory.path(),
            Some(&configuration),
            &resolver,
            second_offer,
        )
        .expect("inspect RetroArch update");
        assert_eq!(second_state.action, RetroArchInstallAction::Update);
        let second = install_managed_retroarch(
            directory.path().to_path_buf(),
            resolver.clone(),
            Vec::new(),
            second_state,
            Box::new(FileRetroArchReleaseTransport::new(fixture.path())),
            Arc::new(AtomicBool::new(false)),
            |_, _| {},
        )
        .expect("update managed RetroArch");
        assert_eq!(second.manifest.version, "1.22.3");
        assert_eq!(
            fs::read(&second.executable).unwrap(),
            b"second RetroArch AppImage\n"
        );
        assert_eq!(
            fs::read(&second.emulator_write.backup).unwrap(),
            before_update_xml
        );
        assert_eq!(
            fs::read(&user_configuration).unwrap(),
            b"user configuration\n"
        );
        assert_eq!(fs::read(&user_save).unwrap(), b"user save\n");

        let core = install_directory.join(
            "RetroArch-Linux-x86_64.AppImage.home/.config/retroarch/cores/fixture_libretro.so",
        );
        fs::write(&core, b"user modified managed core\n").unwrap();
        let configuration = AuxiliaryDocument::load(&emulator_document)
            .unwrap()
            .emulator_configuration()
            .unwrap();
        let repair = inspect_retroarch_release_state(
            directory.path(),
            Some(&configuration),
            &resolver,
            retroarch_linux_test_offer(
                fixture.path(),
                "1.22.3",
                b"second RetroArch AppImage\n",
                b"second fixture core\n",
            ),
        )
        .expect("inspect RetroArch repair");
        assert_eq!(repair.action, RetroArchInstallAction::Repair);
        let blocked =
            inspect_managed_retroarch_removal(directory.path(), Some(&configuration), &resolver)
                .expect("review modified RetroArch removal");
        assert!(!blocked.can_remove);
        fs::write(&core, b"second fixture core\n").unwrap();

        let removable =
            inspect_managed_retroarch_removal(directory.path(), Some(&configuration), &resolver)
                .expect("review removable RetroArch");
        assert!(removable.can_remove);
        let owned_file_count = removable.audit.as_ref().unwrap().installed_files.len();
        let removed = remove_managed_retroarch(directory.path().to_path_buf(), resolver, removable)
            .expect("remove managed RetroArch");
        assert_eq!(
            removed.removed_file_count,
            owned_file_count.saturating_add(1)
        );
        assert!(removed.removed_emulator.is_some());
        assert!(!second.executable.exists());
        assert!(!install_directory
            .join(MANAGED_INSTALL_MANIFEST_NAME)
            .exists());
        assert_eq!(
            fs::read(&user_configuration).unwrap(),
            b"user configuration\n"
        );
        assert_eq!(fs::read(&user_save).unwrap(), b"user save\n");
        assert!(pending_transaction_manifests(directory.path())
            .unwrap()
            .is_empty());
    }

    #[cfg(unix)]
    #[test]
    fn official_shaped_xemu_windows_and_macos_zips_keep_exact_native_layouts() {
        use std::os::unix::fs::PermissionsExt;

        let library = tempfile::tempdir().expect("temporary library");
        let fixture = tempfile::tempdir().expect("release fixture");

        let windows_source = fixture.path().join("windows-source");
        fs::create_dir(&windows_source).unwrap();
        fs::write(windows_source.join("LICENSE.txt"), b"Xemu license\n").unwrap();
        fs::write(windows_source.join("xemu.exe"), b"Windows Xemu\n").unwrap();
        let windows_offer = xemu_zip_test_offer(
            fixture.path(),
            &windows_source,
            "0.8.136",
            XemuArtifactKind::WindowsZipX64,
            &["LICENSE.txt", "xemu.exe"],
        );
        let windows_staging = tempfile::tempdir_in(library.path()).unwrap();
        let mut windows = prepare_xemu_artifact(
            library.path(),
            &windows_offer,
            &fixture.path().join(&windows_offer.asset_name),
            windows_staging.path(),
        )
        .expect("prepare official-shaped Windows Xemu ZIP");
        windows.sort_by(|left, right| left.relative_target.cmp(&right.relative_target));
        assert_eq!(
            windows
                .iter()
                .map(|file| file.relative_target.as_path())
                .collect::<Vec<_>>(),
            [Path::new("LICENSE.txt"), Path::new("xemu.exe")]
        );
        let windows_executable = windows
            .iter()
            .find(|file| file.relative_target == Path::new("xemu.exe"))
            .unwrap();
        assert!(windows_executable.preserve_permissions);
        assert_ne!(
            fs::metadata(&windows_executable.source)
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );

        let macos_source = fixture.path().join("macos-source");
        let macos_executable = macos_source.join("xemu.app/Contents/MacOS/xemu");
        let macos_library = macos_source.join("xemu.app/Contents/Frameworks/libMoltenVK.dylib");
        fs::create_dir_all(macos_executable.parent().unwrap()).unwrap();
        fs::create_dir_all(macos_library.parent().unwrap()).unwrap();
        fs::write(macos_source.join("LICENSE.txt"), b"Xemu license\n").unwrap();
        fs::write(
            macos_source.join("xemu.app/Contents/Info.plist"),
            b"<plist/>\n",
        )
        .unwrap();
        fs::write(&macos_executable, b"universal macOS Xemu\n").unwrap();
        fs::write(&macos_library, b"universal library\n").unwrap();
        fs::set_permissions(&macos_executable, fs::Permissions::from_mode(0o755)).unwrap();
        fs::set_permissions(&macos_library, fs::Permissions::from_mode(0o744)).unwrap();
        let macos_offer = xemu_zip_test_offer(
            fixture.path(),
            &macos_source,
            "0.8.136",
            XemuArtifactKind::MacosUniversalZip,
            &["LICENSE.txt", "xemu.app"],
        );
        let macos_staging = tempfile::tempdir_in(library.path()).unwrap();
        let mut macos = prepare_xemu_artifact(
            library.path(),
            &macos_offer,
            &fixture.path().join(&macos_offer.asset_name),
            macos_staging.path(),
        )
        .expect("prepare official-shaped universal macOS Xemu ZIP");
        macos.sort_by(|left, right| left.relative_target.cmp(&right.relative_target));
        assert_eq!(
            macos
                .iter()
                .map(|file| file.relative_target.as_path())
                .collect::<Vec<_>>(),
            [
                Path::new("LICENSE.txt"),
                Path::new("xemu.app/Contents/Frameworks/libMoltenVK.dylib"),
                Path::new("xemu.app/Contents/Info.plist"),
                Path::new("xemu.app/Contents/MacOS/xemu"),
            ]
        );
        assert!(macos.iter().all(|file| file.preserve_permissions));
        let prepared_executable = macos
            .iter()
            .find(|file| file.relative_target == Path::new("xemu.app/Contents/MacOS/xemu"))
            .unwrap();
        assert_ne!(
            fs::metadata(&prepared_executable.source)
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );
    }

    #[cfg(unix)]
    #[test]
    fn retroarch_macos_dmg_placeholders_become_exact_safe_bundle_links() {
        use std::os::unix::fs::PermissionsExt;

        let extraction = tempfile::tempdir().expect("temporary DMG extraction");
        let bundle = extraction.path().join("RetroArch/RetroArch.app");
        let required = [
            (
                "Contents/MacOS/RetroArch",
                b"universal RetroArch".as_slice(),
            ),
            ("Contents/Info.plist", b"<plist/>".as_slice()),
            (
                "Contents/_CodeSignature/CodeResources",
                b"signed resources".as_slice(),
            ),
            ("Contents/Resources/assets.zip", b"assets".as_slice()),
            (
                "Contents/Frameworks/MoltenVK.framework/Versions/A/MoltenVK",
                b"universal MoltenVK".as_slice(),
            ),
            (
                "Contents/Frameworks/MoltenVK-v1.2.7.framework/Versions/A/MoltenVK-v1.2.7",
                b"universal MoltenVK 1.2.7".as_slice(),
            ),
        ];
        let mut files = Vec::new();
        for (relative, bytes) in required {
            let path = bundle.join(relative);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, bytes).unwrap();
            files.push(path);
        }
        for (relative, target) in RETROARCH_MACOS_BUNDLE_LINKS {
            let relative = Path::new(relative)
                .strip_prefix("RetroArch.app")
                .expect("bundle-relative link");
            let path = bundle.join(relative);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(&path, target.as_bytes()).unwrap();
            files.push(path);
        }
        let prepared =
            prepare_retroarch_macos_extracted(extraction.path(), files).expect("prepare app");
        let links = prepared
            .iter()
            .filter_map(|entry| match entry {
                PreparedRetroArchEntry::Link {
                    source,
                    relative_target,
                    target,
                } => Some((source, relative_target, target)),
                PreparedRetroArchEntry::File(_) => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(links.len(), RETROARCH_MACOS_BUNDLE_LINKS.len());
        for (relative, target) in RETROARCH_MACOS_BUNDLE_LINKS {
            let (_, _, prepared_target) = links
                .iter()
                .find(|(_, prepared_relative, _)| {
                    prepared_relative.as_path() == Path::new(relative)
                })
                .expect("exact managed framework link");
            assert_eq!(prepared_target.as_path(), Path::new(target));
            let extracted_link = bundle.join(
                Path::new(relative)
                    .strip_prefix("RetroArch.app")
                    .expect("bundle-relative link"),
            );
            assert_eq!(
                fs::read_link(extracted_link).unwrap(),
                PathBuf::from(target)
            );
        }
        let executable = prepared
            .iter()
            .find_map(|entry| match entry {
                PreparedRetroArchEntry::File(file)
                    if file.relative_target
                        == Path::new("RetroArch.app/Contents/MacOS/RetroArch") =>
                {
                    Some(file)
                }
                _ => None,
            })
            .expect("managed app executable");
        assert!(executable.preserve_permissions);
        assert_ne!(
            fs::metadata(&executable.source)
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );

        let unsafe_placeholder =
            bundle.join("Contents/Frameworks/MoltenVK.framework/Versions/Current");
        fs::remove_file(&unsafe_placeholder).unwrap();
        fs::write(&unsafe_placeholder, b"../../escape").unwrap();
        let mut unsafe_files = prepared
            .into_iter()
            .map(|entry| match entry {
                PreparedRetroArchEntry::File(file) => file.source,
                PreparedRetroArchEntry::Link { source, .. } => {
                    if source == unsafe_placeholder {
                        source
                    } else {
                        fs::remove_file(&source).unwrap();
                        let expected = RETROARCH_MACOS_BUNDLE_LINKS
                            .iter()
                            .find(|(relative, _)| {
                                bundle.join(
                                    Path::new(relative)
                                        .strip_prefix("RetroArch.app")
                                        .expect("bundle-relative link"),
                                ) == source
                            })
                            .map(|(_, target)| *target)
                            .unwrap();
                        fs::write(&source, expected.as_bytes()).unwrap();
                        source
                    }
                }
            })
            .collect::<Vec<_>>();
        unsafe_files.sort();
        let failure = prepare_retroarch_macos_extracted(extraction.path(), unsafe_files)
            .expect_err("reject changed framework-link target");
        assert!(matches!(
            failure,
            EmulatorWriteFailure::Other(message)
                if message.contains("unexpected target")
        ));
    }

    #[cfg(unix)]
    #[test]
    fn managed_xemu_install_update_repair_review_and_removal_are_native_and_exact() {
        use std::os::unix::fs::PermissionsExt;

        let directory = tempfile::tempdir().expect("temporary library");
        let fixture = tempfile::tempdir().expect("release fixture");
        let data = directory.path().join("Data");
        fs::create_dir(&data).expect("create Data");
        let emulator_document = data.join("Emulators.xml");
        fs::copy(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../fixtures/launchbox/Data/Emulators.xml"),
            &emulator_document,
        )
        .unwrap();
        let platform_directory = data.join("Platforms");
        fs::create_dir(&platform_directory).unwrap();
        let platform_fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/launchbox/Data/Platforms/Fixture Console.xml");
        let platform_document = platform_directory.join("Fixture Console.xml");
        fs::copy(&platform_fixture, &platform_document).unwrap();
        let original_xml = fs::read(&emulator_document).unwrap();
        let resolver = HostPathResolver::default();
        let platforms = vec!["Microsoft Xbox".into()];
        let first_offer =
            xemu_linux_test_offer(fixture.path(), "0.8.135", b"first Xemu AppImage\n");
        let first_state = inspect_xemu_release_state(
            directory.path(),
            Some(
                &AuxiliaryDocument::load(&emulator_document)
                    .unwrap()
                    .emulator_configuration()
                    .unwrap(),
            ),
            &resolver,
            first_offer,
        )
        .expect("inspect initial Xemu install");
        assert_eq!(first_state.action, XemuInstallAction::Install);

        let first = install_managed_xemu(
            directory.path().to_path_buf(),
            resolver.clone(),
            platforms.clone(),
            first_state,
            Box::new(FileReleaseTransport::new(fixture.path())),
            Arc::new(AtomicBool::new(false)),
            |_, _| {},
        )
        .expect("install managed Xemu");
        assert_eq!(first.manifest.profile_id, "xemu");
        assert_eq!(first.manifest.provider, XEMU_PROVIDER);
        assert_eq!(first.manifest.version, "0.8.135");
        assert_eq!(first.manifest.tag, "v0.8.135");
        assert_eq!(
            first.manifest.artifact_kind,
            XemuArtifactKind::LinuxAppImageX64.id()
        );
        assert!(first.manifest.asset_fnv1a64.is_none());
        assert_eq!(
            fs::read(&first.emulator_write.backup).unwrap(),
            original_xml
        );
        assert_eq!(
            fs::read(&first.executable).unwrap(),
            b"first Xemu AppImage\n"
        );
        assert_ne!(
            fs::metadata(&first.executable)
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );
        assert_eq!(
            first.emulator_write.emulator.application_path,
            r"Emulators\Xemu\xemu.AppImage"
        );
        assert_eq!(
            first.emulator_write.emulator.command_line.as_deref(),
            Some("-full-screen -dvd_path")
        );
        assert_eq!(first.emulator_write.mapping_count, 1);
        let xbox_mapping = first
            .emulator_write
            .configuration
            .platforms
            .iter()
            .find(|mapping| {
                mapping
                    .emulator_id
                    .eq_ignore_ascii_case(&first.emulator_write.emulator.id)
            })
            .expect("managed Xemu platform mapping");
        assert_eq!(xbox_mapping.platform, "Microsoft Xbox");
        assert!(xbox_mapping.default);

        let install_directory = directory.path().join("Emulators/Xemu");
        let user_configuration = install_directory.join("xemu.toml");
        let user_bios = install_directory.join("bios/Complex_4627.bin");
        fs::create_dir_all(user_bios.parent().unwrap()).unwrap();
        fs::write(&user_configuration, b"[display]\nscale = 2\n").unwrap();
        fs::write(&user_bios, b"user supplied firmware\n").unwrap();
        let configuration = AuxiliaryDocument::load(&emulator_document)
            .unwrap()
            .emulator_configuration()
            .unwrap();
        let before_update_xml = fs::read(&emulator_document).unwrap();
        let second_offer =
            xemu_linux_test_offer(fixture.path(), "0.8.136", b"second Xemu AppImage\n");
        let second_state = inspect_xemu_release_state(
            directory.path(),
            Some(&configuration),
            &resolver,
            second_offer,
        )
        .expect("inspect managed Xemu update");
        assert_eq!(second_state.action, XemuInstallAction::Update);
        let second = install_managed_xemu(
            directory.path().to_path_buf(),
            resolver.clone(),
            platforms,
            second_state,
            Box::new(FileReleaseTransport::new(fixture.path())),
            Arc::new(AtomicBool::new(false)),
            |_, _| {},
        )
        .expect("update managed Xemu");
        assert_eq!(second.manifest.version, "0.8.136");
        assert_eq!(
            fs::read(&second.executable).unwrap(),
            b"second Xemu AppImage\n"
        );
        assert_ne!(
            fs::metadata(&second.executable)
                .unwrap()
                .permissions()
                .mode()
                & 0o111,
            0
        );
        assert_eq!(
            fs::read(&second.emulator_write.backup).unwrap(),
            before_update_xml
        );
        assert!(second
            .recovery_files
            .iter()
            .any(|path| { fs::read(path).is_ok_and(|bytes| bytes == b"first Xemu AppImage\n") }));
        assert_eq!(
            fs::read(&user_configuration).unwrap(),
            b"[display]\nscale = 2\n"
        );
        assert_eq!(fs::read(&user_bios).unwrap(), b"user supplied firmware\n");

        fs::write(&second.executable, b"user modified managed AppImage\n").unwrap();
        let configuration = AuxiliaryDocument::load(&emulator_document)
            .unwrap()
            .emulator_configuration()
            .unwrap();
        let repair = inspect_xemu_release_state(
            directory.path(),
            Some(&configuration),
            &resolver,
            xemu_linux_test_offer(fixture.path(), "0.8.136", b"second Xemu AppImage\n"),
        )
        .expect("inspect Xemu repair");
        assert_eq!(repair.action, XemuInstallAction::Repair);
        let blocked =
            inspect_managed_xemu_removal(directory.path(), Some(&configuration), &resolver)
                .expect("review modified Xemu removal");
        assert!(!blocked.can_remove);
        assert!(blocked
            .blocked_reason
            .as_deref()
            .is_some_and(|reason| reason.contains("xemu.AppImage is modified")));
        fs::write(&second.executable, b"second Xemu AppImage\n").unwrap();

        let referenced_xml = fs::read_to_string(&platform_fixture)
            .unwrap()
            .replace("fixture-emulator", &second.emulator_write.emulator.id);
        fs::write(&platform_document, referenced_xml).unwrap();
        let referenced =
            inspect_managed_xemu_removal(directory.path(), Some(&configuration), &resolver)
                .expect("review referenced Xemu removal");
        assert!(!referenced.can_remove);
        assert!(referenced.reference_count > 0);
        fs::copy(&platform_fixture, &platform_document).unwrap();

        let removable =
            inspect_managed_xemu_removal(directory.path(), Some(&configuration), &resolver)
                .expect("review removable Xemu");
        assert!(removable.can_remove);
        assert_eq!(removable.audit.as_ref().unwrap().installed_files.len(), 1);
        let removed = remove_managed_xemu(directory.path().to_path_buf(), resolver, removable)
            .expect("remove managed Xemu");
        assert_eq!(removed.removed_file_count, 2);
        assert_eq!(removed.recovery_files.len(), 2);
        assert!(removed.removed_emulator.is_some());
        assert!(!second.executable.exists());
        assert!(!install_directory
            .join(MANAGED_INSTALL_MANIFEST_NAME)
            .exists());
        assert_eq!(
            fs::read(&user_configuration).unwrap(),
            b"[display]\nscale = 2\n"
        );
        assert_eq!(fs::read(&user_bios).unwrap(), b"user supplied firmware\n");
        assert!(install_directory.join("bios").is_dir());
        assert!(pending_transaction_manifests(directory.path())
            .unwrap()
            .is_empty());
    }

    #[cfg(unix)]
    fn bigpemu_linux_test_offer(fixture: &Path, version: &str) -> BigPEmuReleaseOffer {
        use std::os::unix::fs::PermissionsExt;

        let compact = version.replace('.', "");
        let source = fixture.join(format!("bigpemu-source-{compact}"));
        let package = source.join("bigpemu");
        fs::create_dir_all(package.join("Data")).unwrap();
        fs::write(
            package.join("bigpemu"),
            format!("native BigPEmu {version}\n"),
        )
        .unwrap();
        let mut executable_permissions =
            fs::metadata(package.join("bigpemu")).unwrap().permissions();
        executable_permissions.set_mode(0o755);
        fs::set_permissions(package.join("bigpemu"), executable_permissions).unwrap();
        fs::write(
            package.join("ReadMe.txt"),
            format!("BigPEmu version {version}\n"),
        )
        .unwrap();
        fs::write(
            package.join(format!("Data/release-{compact}.dat")),
            format!("provider data {version}\n"),
        )
        .unwrap();
        fs::write(
            package.join("make_desktop.sh"),
            b"deliberately invalid helper fixture",
        )
        .unwrap();

        let asset_name = format!("BigPEmu_Linux64_v{compact}.tar.gz");
        let asset = fixture.join(&asset_name);
        let tar = fixture.join(format!("BigPEmu_Linux64_v{compact}.tar"));
        let tar_output = Command::new("7z")
            .current_dir(&source)
            .arg("a")
            .arg("-ttar")
            .arg("-bd")
            .arg("-bb0")
            .arg("-y")
            .arg(&tar)
            .arg("--")
            .arg("bigpemu")
            .output()
            .unwrap();
        assert!(
            tar_output.status.success(),
            "could not create BigPEmu tar: {}",
            String::from_utf8_lossy(&tar_output.stderr)
        );
        let gzip_output = Command::new("7z")
            .current_dir(fixture)
            .arg("a")
            .arg("-tgzip")
            .arg("-bd")
            .arg("-bb0")
            .arg("-y")
            .arg(&asset)
            .arg("--")
            .arg(tar.file_name().unwrap())
            .output()
            .unwrap();
        assert!(
            gzip_output.status.success(),
            "could not create BigPEmu gzip: {}",
            String::from_utf8_lossy(&gzip_output.stderr)
        );
        fs::remove_file(tar).unwrap();
        let bytes = fs::read(&asset).unwrap();
        let mut fnv = 0xcbf2_9ce4_8422_2325_u64;
        for byte in &bytes {
            fnv ^= u64::from(*byte);
            fnv = fnv.wrapping_mul(0x0000_0100_0000_01b3);
        }
        BigPEmuReleaseOffer {
            version: version.into(),
            release_name: format!("BigPEmu {version}"),
            release_url: lb_integrations::bigpemu::BIGPEMU_DOWNLOAD_PAGE.into(),
            artifact_kind: BigPEmuArtifactKind::LinuxTarGzX64,
            asset_name: asset_name.clone(),
            asset_url: format!("https://www.richwhitehouse.com/jaguar/builds/{asset_name}"),
            asset_byte_len: u64::try_from(bytes.len()).unwrap(),
            asset_fnv1a64: format!("{fnv:016X}"),
        }
    }

