    #[test]
    fn big_box_playlist_actions_only_offer_manual_membership_changes() {
        let playlist = |id: &str,
                        name: &str,
                        auto_populate: bool,
                        is_autogenerated: bool,
                        game_ids: &[&str]| {
            PlaylistDocument {
                playlist: Playlist {
                    id: id.into(),
                    metadata: NavigationMetadata {
                        name: name.into(),
                        ..NavigationMetadata::default()
                    },
                    auto_populate,
                    is_autogenerated,
                    ..Playlist::default()
                },
                games: game_ids
                    .iter()
                    .map(|game_id| PlaylistGame {
                        game_id: (*game_id).into(),
                        game_title: format!("Title {game_id}"),
                        game_platform: "Fixture Console".into(),
                        ..PlaylistGame::default()
                    })
                    .collect(),
                ..PlaylistDocument::default()
            }
        };
        let catalog = NavigationCatalog {
            playlists: vec![
                playlist("manual-zulu", "Zulu", false, false, &[]),
                playlist(
                    "manual-current",
                    "Current",
                    false,
                    false,
                    &["fixture-adventure"],
                ),
                playlist("auto-list", "Automatic", true, false, &[]),
                playlist("generated-list", "Generated", false, true, &[]),
                playlist("manual-alpha", "alpha", false, false, &[]),
            ],
            ..NavigationCatalog::default()
        };

        let payload =
            big_box_playlist_action_payload("FIXTURE-ADVENTURE", Some("MANUAL-CURRENT"), &catalog);
        assert_eq!(payload.version, BIG_BOX_PLAYLIST_ACTION_PAYLOAD_VERSION);
        assert_eq!(payload.game_id, "FIXTURE-ADVENTURE");
        assert_eq!(
            payload
                .add_targets
                .iter()
                .map(|target| (target.playlist_id.as_str(), target.name.as_str()))
                .collect::<Vec<_>>(),
            [("manual-alpha", "alpha"), ("manual-zulu", "Zulu")]
        );
        assert_eq!(
            payload.remove_current,
            Some(BigBoxPlaylistActionTargetPayload {
                playlist_id: "manual-current".into(),
                name: "Current".into(),
            })
        );

        let derived_current =
            big_box_playlist_action_payload("fixture-adventure", Some("auto-list"), &catalog);
        assert!(derived_current.remove_current.is_none());
        assert!(derived_current
            .add_targets
            .iter()
            .all(|target| target.playlist_id != "auto-list"
                && target.playlist_id != "generated-list"));
    }

    #[test]
    fn big_box_playlist_membership_write_is_transactional_and_lossless() {
        let directory = tempfile::tempdir().expect("temporary library");
        let playlist_directory = directory.path().join("Data/Playlists");
        fs::create_dir_all(&playlist_directory).expect("create playlist directory");
        let source = playlist_directory.join("Manual Picks.xml");
        let original = br#"<?xml version="1.0" encoding="utf-8"?>
<LaunchBox>
  <Playlist>
    <PlaylistId>manual-playlist</PlaylistId>
    <Name>Manual Picks</Name>
    <NestedName>Manual Picks</NestedName>
    <Notes>Lossless BigBox membership fixture.</Notes>
    <HideInBigBox>false</HideInBigBox>
    <LocalDbParsed>true</LocalDbParsed>
    <AutoPopulate>false</AutoPopulate>
    <IncludeWithPlatforms>false</IncludeWithPlatforms>
    <IsAutogenerated>false</IsAutogenerated>
    <SortBy>Title</SortBy>
    <FuturePlaylistField>keep-manual</FuturePlaylistField>
  </Playlist>
  <PlaylistGame>
    <GameId>fixture-puzzle</GameId>
    <GameTitle>Fixture Puzzle</GameTitle>
    <GamePlatform>Fixture Console</GamePlatform>
    <GameFileName>fixture-puzzle.rom</GameFileName>
    <LaunchBoxDbId>4321</LaunchBoxDbId>
    <ManualOrder>4</ManualOrder>
    <FutureGameField>keep-puzzle</FutureGameField>
  </PlaylistGame>
  <FutureRootField>keep-root</FutureRootField>
</LaunchBox>
"#;
        fs::write(&source, original).expect("write manual playlist");
        let game = Game {
            id: "fixture-adventure".into(),
            title: "Fixture Adventure".into(),
            platform: "Fixture Console".into(),
            application_path: r"Games\Fixture Console\fixture-adventure.rom".into(),
            database_id: Some(1234),
            ..Game::default()
        };

        let added = write_big_box_playlist_membership(
            directory.path().to_path_buf(),
            source.clone(),
            game.clone(),
            true,
        )
        .unwrap_or_else(|error| {
            panic!(
                "add BigBox playlist membership failed: {}",
                describe_platform_write_failure(&error)
            )
        });
        assert!(added.present);
        assert_eq!(fs::read(&added.backup).expect("read add backup"), original);
        let intermediate = fs::read(&source).expect("read added playlist");
        let intermediate_text = String::from_utf8_lossy(&intermediate);
        assert!(
            intermediate_text.contains("<FuturePlaylistField>keep-manual</FuturePlaylistField>")
        );
        assert!(intermediate_text.contains("<FutureGameField>keep-puzzle</FutureGameField>"));
        assert!(intermediate_text.contains("<FutureRootField>keep-root</FutureRootField>"));
        assert!(intermediate_text.contains("<GameId>fixture-adventure</GameId>"));
        assert!(intermediate_text.contains("<GameFileName>fixture-adventure.rom</GameFileName>"));
        assert!(intermediate_text.contains("<LaunchBoxDbId>1234</LaunchBoxDbId>"));
        assert!(intermediate_text.contains("<ManualOrder>-1</ManualOrder>"));

        let removed = write_big_box_playlist_membership(
            directory.path().to_path_buf(),
            source.clone(),
            game,
            false,
        )
        .unwrap_or_else(|error| {
            panic!(
                "remove BigBox playlist membership failed: {}",
                describe_platform_write_failure(&error)
            )
        });
        assert!(!removed.present);
        assert_eq!(
            fs::read(&removed.backup).expect("read removal backup"),
            intermediate
        );
        let final_bytes = fs::read(&source).expect("read final playlist");
        let final_text = String::from_utf8_lossy(&final_bytes);
        assert!(!final_text.contains("<GameId>fixture-adventure</GameId>"));
        assert!(final_text.contains("<GameId>fixture-puzzle</GameId>"));
        assert!(final_text.contains("<ManualOrder>4</ManualOrder>"));
        assert!(final_text.contains("<FuturePlaylistField>keep-manual</FuturePlaylistField>"));
        assert!(final_text.contains("<FutureGameField>keep-puzzle</FutureGameField>"));
        assert!(final_text.contains("<FutureRootField>keep-root</FutureRootField>"));
        assert_ne!(added.backup, removed.backup);
        assert!(pending_transaction_manifests(directory.path())
            .expect("inspect transaction manifests")
            .is_empty());
    }

    #[test]
    fn nested_navigation_flattens_categories_and_filters_descendant_platforms() {
        let catalog = NavigationCatalog {
            platforms: Vec::new(),
            categories: vec![
                PlatformCategory {
                    metadata: NavigationMetadata {
                        name: "Systems".into(),
                        nested_name: Some("All Systems".into()),
                        ..NavigationMetadata::default()
                    },
                    ..PlatformCategory::default()
                },
                PlatformCategory {
                    metadata: NavigationMetadata {
                        name: "Handhelds".into(),
                        ..NavigationMetadata::default()
                    },
                    ..PlatformCategory::default()
                },
            ],
            parents: vec![
                ParentRelationship {
                    platform_category_name: Some("Systems".into()),
                    ..ParentRelationship::default()
                },
                ParentRelationship {
                    platform_category_name: Some("Handhelds".into()),
                    parent_platform_category_name: Some("Systems".into()),
                    ..ParentRelationship::default()
                },
                ParentRelationship {
                    platform_name: Some("Game Boy".into()),
                    parent_platform_category_name: Some("Handhelds".into()),
                    ..ParentRelationship::default()
                },
                ParentRelationship {
                    platform_name: Some("Arcade".into()),
                    ..ParentRelationship::default()
                },
            ],
            ..NavigationCatalog::default()
        };
        let games = vec![
            Game {
                id: "handheld-game".into(),
                platform: "Game Boy".into(),
                ..Game::default()
            },
            Game {
                id: "arcade-game".into(),
                platform: "Arcade".into(),
                ..Game::default()
            },
        ];
        let (entries, category_platforms, category_game_ids, playlist_game_ids) =
            build_navigation_entries(&catalog, &["Game Boy".into(), "Arcade".into()], &games);
        assert_eq!(
            entries
                .iter()
                .map(|entry| (
                    entry.kind,
                    entry.key.as_str(),
                    entry.depth,
                    entry.game_count
                ))
                .collect::<Vec<_>>(),
            [
                ("platform", "Arcade", 0, 1),
                ("category", "Systems", 0, 1),
                ("category", "Handhelds", 1, 1),
                ("platform", "Game Boy", 2, 1),
            ]
        );
        assert_eq!(
            category_platforms["systems"]
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            ["game boy"]
        );
        assert_eq!(
            category_game_ids["systems"],
            BTreeSet::from(["handheld-game".into()])
        );
        assert!(playlist_game_ids.is_empty());
    }

